    "build": "tsc -b",
    "check": "tsc -b --pretty false",
    "typecheck": "tsc -b --pretty false"
  }
}

import {
  drizzleInstrumentationOf,
  inheritNativeLeases,
  runSpecializedTrace,
  squashDrizzleCause,
} from "@relkit/drizzle/internal";
import type { Auth } from "better-auth";
import { Cause, Effect, Exit, Layer, ManagedRuntime } from "effect";
import type { BetterAuthActivationOptions } from "./activation.types.js";
import { AuthFailure } from "./auth.errors.js";
import { AuthService, authLiveLayer, authNativeOf } from "./auth.service.js";
import type {
  AuthDatabase,
  BetterAuthRuntime,
  BetterAuthServiceDescriptor,
  BetterAuthServiceOptions,
} from "./auth.types.js";
import { BETTER_AUTH_RUNTIME } from "./symbols.js";

/**
 * Binds native auth to an acquired database and its declared ALL route.
 * @typeParam Options - Native configuration retained by the lazy declaration.
 * @param service - Shared acquisition captures the first database and route prefix.
 * @param database - Borrowed database; auth never owns or disposes it.
 * @param basePath - Route-derived prefix validated during acquisition.
 * @param options - Isolation leaves the descriptor handler target untouched.
 * @returns Native auth preserving options, session inference and endpoint properties.
 * @remarks Layer acquisition is independent of waiting callers. Failures evict the
 * shared attempt; successful auth remains retained after database close.
 * @example
 * ```ts
 * import { activateBetterAuthService, defineBetterAuthService, type AuthConfiguration } from "@relkit/better-auth";
 * async function handleNativeAuth(database: AuthConfiguration["database"]): Promise<Response> {
 *   const service = defineBetterAuthService({ baseURL: "http://localhost" });
 *   const auth = await activateBetterAuthService(service, database, "/api/auth", { isolated: true });
 *   return auth.handler(new Request("http://localhost/api/auth/get-session"));
 * }
 * // The application retains database ownership until admitted work completes.
 * ```
 */
export async function activateBetterAuthService<Options extends BetterAuthServiceOptions>(
  service: BetterAuthServiceDescriptor<Options>,
  database: AuthDatabase,
  basePath: string,
  options: BetterAuthActivationOptions = {},
): Promise<Auth<any>> {
  const state = runtimeOf(service);
  let owner = options.isolated === true ? undefined : state.activation;
  if (owner === undefined) {
    if (!Reflect.has(database, Symbol.for("relkit.drizzle.service")))
      throw new TypeError("Drizzle activation is missing its service");
    const instrumentation = drizzleInstrumentationOf(database);
    // Captured diagnostics apply both during Layer acquisition and subsequent native calls.
    owner = ManagedRuntime.make(
      authLiveLayer({ options: state.options, database, basePath }).pipe(
        Layer.provideMerge(Layer.succeedContext(instrumentation)),
      ),
    );
    if (options.isolated !== true) state.activation = owner;
  }
  const currentOwner = owner;
  try {
    return await runAuthPromise(
      currentOwner,
      Effect.flatMap(AuthService, (auth) =>
        Effect.sync(() => authNativeAdapter(currentOwner, authNativeOf(auth))),
      ),
      undefined,
      "auth.acquire",
    );
  } catch (error) {
    if (state.activation === currentOwner) state.activation = undefined;
    await currentOwner.dispose();
    throw error;
  }
}

/**
 * Runs the Promise boundary, unwrapping expected auth failures.
 * @typeParam A - Successful operation result.
 * @typeParam E - Effect failure channel.
 * @typeParam R - Runtime's provided services.
 * @typeParam ER - Runtime acquisition failures.
 * @param runtime - Managed auth owner.
 * @param effect - Lazy operation preserving defects and interruption.
 * @param options - Request cancellation forwarded to the runner.
 * @param operation - Bounded invocation label; the trace captures no SDK result.
 * @returns Promise preserving native exception identity and mixed causes.
 * @internal
 */
export function runAuthPromise<A, E, R, ER>(
  runtime: ManagedRuntime.ManagedRuntime<R, ER>,
  effect: Effect.Effect<A, E, R>,
  options?: Effect.RunOptions,
  operation = "auth.api",
): Promise<A> {
  const admittedEffect = inheritNativeLeases(effect);
  return runSpecializedTrace(operation, async () => {
    const exit = await runtime.runPromiseExit(admittedEffect, options);
    if (Exit.isSuccess(exit)) return exit.value;
    // Unwrap auth causes before the shared renderer retains every cleanup/interrupt reason.
    throw squashDrizzleCause(
      Cause.map(exit.cause, (failure) =>
        failure instanceof AuthFailure ? failure.cause : failure,
      ),
    );
  });
}

/**
 * Routes native callables through admission while preserving native properties.
 * @param owner - Managed owner reused by each Promise boundary.
 * @param native - SDK instance with initialization complete.
 * @returns Stable proxy retaining native object and function metadata.
 * @remarks Handler, fetch and API calls are admitted. The native $context is
 * retained as an advanced SDK view; direct adapter access requires its DB owner's
 * lifetime rather than establishing a new admission lease.
 * @internal
 */
export function authNativeAdapter(
  owner: BetterAuthRuntime<BetterAuthServiceOptions>["activation"] & {},
  native: Auth<any>,
): Auth<any> {
  const cached = nativeAdapters.get(owner);
  if (cached !== undefined) return cached;
  const methods = new Map<PropertyKey, unknown>();
  const handler = (request: Request) =>
    runAuthPromise(
      owner,
      Effect.flatMap(AuthService, (auth) => auth.handler(request)),
      { signal: request.signal },
      "auth.handler",
    );
  const api = new Proxy(native.api, {
    get(target, key, receiver) {
      const value: unknown = Reflect.get(target, key, receiver);
      if (typeof value !== "function" || typeof key !== "string") return value;
      if (!methods.has(key))
        methods.set(
          key,
          new Proxy(value, {
            apply(_method, _receiver, args) {
              return runAuthPromise(
                owner,
                Effect.flatMap(AuthService, (auth) => auth.api(key, args)),
                undefined,
                key === "getSession" ? "auth.session" : "auth.api",
              );
            },
          }),
        );
      return methods.get(key);
    },
  });
  const adapter = new Proxy(native, {
    get(target, key, receiver) {
      if (key === "handler" || key === "fetch") return handler;
      return key === "api" ? api : Reflect.get(target, key, receiver);
    },
  });
  nativeAdapters.set(owner, adapter);
  return adapter;
}

// Owners retain native auth already; this weak projection cache adds no lifetime.
const nativeAdapters = new WeakMap<object, Auth<any>>();

/**
 * Reads the server-only state brand established by defineBetterAuthService.
 * @typeParam Options - Native options held by the declaration.
 * @param service - Auth declaration.
 * @returns Lazy managed-owner state.
 * @throws TypeError When the value is not a supported declaration.
 */
function runtimeOf<Options extends BetterAuthServiceOptions>(
  service: BetterAuthServiceDescriptor<Options>,
): BetterAuthRuntime<Options> {
  const runtime: unknown = Reflect.get(service, BETTER_AUTH_RUNTIME);
  if (
    runtime === null ||
    typeof runtime !== "object" ||
    !("options" in runtime) ||
    !("activation" in runtime)
  )
    throw new TypeError("Invalid Better Auth service descriptor");
  return runtime as BetterAuthRuntime<Options>;
}

import { Schema } from "effect";

/** Typed authentication boundary failure retaining the original SDK exception. */
export class AuthFailure extends Schema.TaggedError<AuthFailure>()("AuthFailure", {
  operation: Schema.String,
  cause: Schema.Defect(),
}) {}

import { betterAuth } from "better-auth";
import {
  nativeCall,
  observeSpecializedOperation,
  redactSpecializedTrace,
} from "@relkit/drizzle/internal";
import { Context, Effect, Layer } from "effect";
import { AuthFailure } from "./auth.errors.js";
import type { AuthFactoryInterface } from "./auth.types.js";

/**
 * Replaceable native SDK factory; auth service acquisition owns async initialization.
 * @remarks This low-level construction dependency returns native callables. Use
 * authServiceLayer to await its eager context initialization under DB admission.
 * @see {@link authFactoryLiveLayer} for composition with the owned auth service.
 */
export class AuthFactory extends Context.Service<AuthFactory, AuthFactoryInterface>()(
  "relkit/AuthFactory",
) {}

/**
 * Production SDK construction layer; acquiring the factory does not create auth.
 * @example
 * ```ts
 * import { Layer } from "effect";
 * import { authFactoryLiveLayer, authServiceLayer, type AuthConfiguration } from "@relkit/better-auth";
 * function createAuthLayer(configuration: AuthConfiguration) {
 *   return authServiceLayer(configuration).pipe(Layer.provide(authFactoryLiveLayer));
 * }
 * ```
 */
export const authFactoryLiveLayer = Layer.effect(
  AuthFactory,
  Effect.gen(function* () {
    return makeAuthFactory((options) =>
      nativeCall("auth.factory", () => betterAuth(options)).pipe(
        Effect.mapError(
          (failure) => new AuthFailure({ operation: "auth.factory", cause: failure.cause }),
        ),
      ),
    );
  }),
);

/**
 * Gives substituted factory implementations the same observable operation contract.
 * @param create - Lazy SDK creation dependency preserving typed failures and defects.
 * @returns Factory service whose bounded diagnostics never record native options.
 * @see {@link authFactoryLiveLayer} for factory provisioning at service acquisition.
 */
export function makeAuthFactory(create: AuthFactoryInterface["create"]): AuthFactoryInterface {
  const namedCreate: AuthFactoryInterface["create"] = Effect.fn("AuthFactory.create")((options) =>
    observeSpecializedOperation("auth.factory", create(options)),
  );
  return AuthFactory.of({
    create: (options) => redactSpecializedTrace(namedCreate(options)),
  });
}

import { Schema } from "effect";

/** Auth route prefixes exclude trailing slashes and dynamic route markers. */
export const AuthBasePath = Schema.String.check(
  Schema.makeFilter(
    (value) =>
      value.startsWith("/") && !value.endsWith("/") && !value.includes("*") && !value.includes("["),
  ),
);

import {
  drizzleRuntimeOf,
  nativeCall,
  observeSpecializedOperation,
  redactSpecializedTrace,
  withDrizzleSqliteWork,
  withDrizzleWork,
} from "@relkit/drizzle/internal";
import { drizzleAdapter } from "better-auth/adapters/drizzle";
import type { Auth } from "better-auth";
import { Context, Effect, Layer, Schema } from "effect";
import { AuthFailure } from "./auth.errors.js";
import { AuthFactory, authFactoryLiveLayer } from "./auth.factory.js";
import { AuthBasePath } from "./auth.schemas.js";
import type { AuthConfiguration, AuthDatabase, AuthServiceInterface } from "./auth.types.js";

/**
 * Native auth service; each method admits DB work and retains SDK completion.
 * @see {@link authServiceLayer} for ownership and a checked composition example.
 */
export class AuthService extends Context.Service<AuthService, AuthServiceInterface>()(
  "relkit/AuthService",
) {}

/**
 * Acquires authentication against a borrowed Drizzle owner using a supplied factory.
 * @param configuration - Auth options, database owner and filesystem route prefix.
 * @returns A lazy layer providing AuthService; failures retain native causes.
 * @remarks SDK initialization and calls finish before database admission ends.
 * This layer never disposes the database. Provide AuthFactory to substitute SDK creation.
 * @example
 * ```ts
 * import { Effect } from "effect";
 * import { AuthService, authLiveLayer, type AuthConfiguration } from "@relkit/better-auth";
 * async function handleAuth(configuration: AuthConfiguration): Promise<Response> {
 *   const program = Effect.flatMap(AuthService, (auth) => auth.handler(new Request("http://localhost/api/auth/session")));
 *   return Effect.runPromise(program.pipe(Effect.provide(authLiveLayer(configuration))));
 * }
 * ```
 */
export function authServiceLayer(configuration: AuthConfiguration) {
  return Layer.effect(
    AuthService,
    observeSpecializedOperation(
      "auth.acquire",
      withAuthWork(
        configuration.database,
        Effect.gen(function* () {
          yield* Schema.decodeUnknownEffect(AuthBasePath)(configuration.basePath).pipe(
            Effect.mapError(
              () =>
                new AuthFailure({
                  operation: "auth.acquire",
                  cause: new TypeError(`Invalid Better Auth base path "${configuration.basePath}"`),
                }),
            ),
          );
          const declaration = databaseServiceOf(configuration.database);
          const database = drizzleRuntimeOf(declaration);
          const factory = yield* AuthFactory;
          const { drizzle: adapterOptions, ...options } = configuration.options;
          const native = yield* factory.create({
            ...options,
            basePath: configuration.basePath,
            database: drizzleAdapter(configuration.database.client, {
              ...(adapterOptions ?? {}),
              schema: adapterOptions?.schema ?? database.schema,
              provider: database.dialect,
            }),
          });
          // Better Auth starts async plugin initialization eagerly; retain the borrow until it settles.
          yield* nativePromise("auth.acquire", () => native.$context);
          const service = AuthService.of({
            handler: Effect.fn("AuthService.handler")((request) =>
              observeSpecializedOperation(
                "auth.handler",
                withAuthWork(
                  configuration.database,
                  nativePromise("auth.handler", () => native.handler(request)),
                ),
              ),
            ),
            api: Effect.fn("AuthService.api")((method, args) => {
              const operation = method === "getSession" ? "auth.session" : "auth.api";
              return observeSpecializedOperation(
                operation,
                withAuthWork(
                  configuration.database,
                  nativePromise(operation, () =>
                    Reflect.apply(Reflect.get(native.api, method), native.api, args),
                  ),
                ),
              );
            }),
          });
          // The adapter must enclose Effect.fn's outer named span as well as its body.
          const protectedService = AuthService.of({
            handler: (request) => redactSpecializedTrace(service.handler(request)),
            api: (method, args) => redactSpecializedTrace(service.api(method, args)),
          });
          nativeInstances.set(protectedService, native);
          return protectedService;
        }).pipe(Effect.uninterruptible),
      ),
    ),
  );
}

// Raw SDK callables remain private; the public service only exposes admitted effects.
const nativeInstances = new WeakMap<AuthServiceInterface, Auth<any>>();

/**
 * Projects a raw SDK instance only at the server's guarded compatibility boundary.
 * @param service - Layer-acquired authentication service.
 * @returns Private native instance for constructing the admitted public SDK proxy.
 * @throws TypeError When a service implementation has no native compatibility view.
 * @internal
 */
export function authNativeOf(service: AuthServiceInterface): Auth<any> {
  const native = nativeInstances.get(service);
  if (native === undefined)
    throw new TypeError("Auth service has no native compatibility instance");
  return native;
}

/**
 * Builds the production authentication service with the native Better Auth factory.
 * @param configuration - Explicit options and an acquired borrowed database.
 * @returns A lazy, substitutable service layer; see authServiceLayer for composition.
 * @see {@link authServiceLayer} for the checked execution and ownership example.
 */
export function authLiveLayer(configuration: AuthConfiguration) {
  return authServiceLayer(configuration).pipe(Layer.provide(authFactoryLiveLayer));
}

/**
 * Bridges an uncancellable SDK Promise while preserving admission until settlement.
 * @typeParam A - Native SDK success value.
 * @param operation - Bounded authentication operation name.
 * @param execute - Lazy SDK call, including synchronous exceptions.
 * @returns A lazy effect with typed SDK failure; interruption resumes after completion.
 */
function nativePromise<A>(operation: string, execute: () => A | PromiseLike<A>) {
  return nativeCall(operation, execute).pipe(
    Effect.mapError((failure) => new AuthFailure({ operation, cause: failure.cause })),
  );
}

/**
 * Borrows the database owner and its physical SQLite execution permit together.
 * @typeParam A - SDK success value.
 * @typeParam E - SDK failure channel.
 * @typeParam R - Caller requirements retained by the borrowed work.
 * @param database - Active owner supplying physical client identity and lifetime.
 * @param effect - SDK work that waits for actual native completion.
 * @returns Lazy admitted work; permit waiting stays interruptible and hooks can reenter.
 */
function withAuthWork<A, E, R>(database: AuthDatabase, effect: Effect.Effect<A, E, R>) {
  return withDrizzleWork(database, withDrizzleSqliteWork(database, effect));
}

/**
 * Reads the native database declaration from the activation's established brand.
 * @param activation - Borrowed active database.
 * @returns Its declaration; invalid runtime values fail with the original TypeError.
 * @throws TypeError When an activation lacks its declaration brand.
 */
function databaseServiceOf(activation: AuthDatabase) {
  const service: unknown = Reflect.get(activation, Symbol.for("relkit.drizzle.service"));
  if (service === null || typeof service !== "object")
    throw new TypeError("Drizzle activation is missing its service");
  // The activation brand is the existing native contract, not a serialized SDK schema.
  return service as Parameters<typeof drizzleRuntimeOf>[0];
}

import type { createDescriptorBase } from "@relkit/contracts";
import type {
  DrizzleActivation,
  DrizzleServiceDescriptor,
  DrizzleFailure,
} from "@relkit/drizzle/internal";
import type { RawHttpHandler } from "@relkit/routes";
import type { Auth, BetterAuthOptions } from "better-auth";
import type { DrizzleAdapterConfig } from "better-auth/adapters/drizzle";
import type { Effect, ManagedRuntime } from "effect";
import type { AuthFailure } from "./auth.errors.js";
import type { AuthService } from "./auth.service.js";
import { BETTER_AUTH_HANDLER } from "./symbols.js";

/** Native options; RELKIT supplies database and the route-derived base path. */
export type BetterAuthServiceOptions = Omit<BetterAuthOptions, "database" | "basePath"> & {
  readonly database?: never;
  readonly basePath?: never;
  readonly drizzle?: Omit<DrizzleAdapterConfig, "provider">;
};

/** Frozen handler registration used by route discovery without acquisition. */
export interface BetterAuthRegistration {
  readonly kind: "better-auth";
  readonly service: BetterAuthServiceDescriptor<any>;
}

/**
 * Route handler carrying native session inference without a live SDK object.
 * @typeParam Session - Native session and user result inferred from auth options.
 */
export type BetterAuthHandler<Session = unknown> = RawHttpHandler & {
  readonly [BETTER_AUTH_HANDLER]: BetterAuthRegistration;
  readonly __session?: Session;
};

/**
 * Extracts native session and user types from an authored auth handler.
 * @typeParam Handler - Branded handler whose phantom session inference is read.
 */
export type InferBetterAuthSession<Handler> =
  Handler extends BetterAuthHandler<infer Session> ? Session : never;

/**
 * Lazy declaration whose handler identity survives activation and isolation.
 * @typeParam Options - Native auth configuration retaining plugin/session inference.
 */
export interface BetterAuthServiceDescriptor<
  Options extends BetterAuthServiceOptions,
> extends ReturnType<typeof createDescriptorBase<"service", string>> {
  readonly capability: { readonly kind: "better-auth" };
  readonly handler: BetterAuthHandler<Auth<Options>["$Infer"]["Session"]>;
}

/** Borrowed database; its Drizzle owner remains solely responsible for disposal. */
export type AuthDatabase = DrizzleActivation<DrizzleServiceDescriptor<any, any, any, any>>;

/** Runtime dependencies captured once when constructing a native auth service. */
export interface AuthConfiguration {
  readonly options: BetterAuthServiceOptions;
  readonly database: AuthDatabase;
  readonly basePath: string;
}

/** Replaceable SDK construction contract; expected SDK failures retain their cause. */
export interface AuthFactoryInterface {
  /**
   * Constructs native auth during service acquisition.
   * @param options - Native options including the owner-supplied database adapter.
   * @returns Lazy factory effect retaining expected SDK failures as AuthFailure.
   */
  readonly create: (options: BetterAuthOptions) => Effect.Effect<Auth<any>, AuthFailure>;
}

/** Effect-native operations sharing one native SDK instance and database admission. */
export interface AuthServiceInterface {
  /**
   * Executes native routing while holding borrowed database admission.
   * @param request - Unmodified native Request, including its cancellation signal.
   * @returns Lazy response effect; SDK failures retain their original cause.
   */
  readonly handler: (request: Request) => Effect.Effect<Response, AuthFailure | DrizzleFailure>;

  /**
   * Executes a native endpoint with its original arguments and callable metadata.
   * @param method - Native API property; diagnostics normalize it to bounded labels.
   * @param args - Native arguments passed without inspecting sensitive payloads.
   * @returns Lazy opaque native result, with admission and SDK typed failures.
   */
  readonly api: (
    method: string,
    args: readonly unknown[],
  ) => Effect.Effect<unknown, AuthFailure | DrizzleFailure>;
}

/**
 * Server-only declaration state: the managed owner, rather than a mutable Promise.
 * @typeParam Options - Options retained by the original authoring declaration.
 */
export interface BetterAuthRuntime<Options extends BetterAuthServiceOptions> {
  readonly options: Options;
  activation: ManagedRuntime.ManagedRuntime<AuthService, AuthFailure | DrizzleFailure> | undefined;
}

/** Lazy authoring and Effect-native authentication borrowing the application's DB. @packageDocumentation */
import { createDescriptorBase } from "@relkit/contracts";
import { createUnboundIdentity } from "@relkit/invocation";
import type { Auth } from "better-auth";
import { Effect } from "effect";
import { activateBetterAuthService, runAuthPromise } from "./activation.js";
import { AuthService } from "./auth.service.js";
import type {
  BetterAuthHandler,
  BetterAuthRuntime,
  BetterAuthServiceDescriptor,
  BetterAuthServiceOptions,
} from "./auth.types.js";
import { BETTER_AUTH_HANDLER, BETTER_AUTH_RUNTIME } from "./symbols.js";

export { activateBetterAuthService };
export { BETTER_AUTH_HANDLER };
export { AuthFailure } from "./auth.errors.js";
export { AuthFactory, authFactoryLiveLayer } from "./auth.factory.js";
export { AuthService, authServiceLayer, authLiveLayer } from "./auth.service.js";
export type { BetterAuthActivationOptions } from "./activation.types.js";
export type {
  BetterAuthServiceOptions,
  BetterAuthRegistration,
  BetterAuthHandler,
  InferBetterAuthSession,
  BetterAuthServiceDescriptor,
  AuthConfiguration,
  AuthServiceInterface,
  AuthFactoryInterface,
} from "./auth.types.js";

/**
 * Defines lazy authentication using the application's Drizzle database.
 * @typeParam Options - Native options retaining session and plugin inference.
 * @param options - Native SDK configuration plus optional Drizzle adapter settings.
 * @returns A frozen declaration and stable handler; inactive handlers return 503.
 * @remarks Mount handler in a filesystem ALL catch-all route. RELKIT supplies
 * database and basePath. Declaration and compilation never construct native auth.
 * Supply BETTER_AUTH_SECRET in the server environment before activation.
 * @throws TypeError When options is not an object or specifies database/basePath.
 * @example
 * ```ts
 * import { defineBetterAuthService } from "@relkit/better-auth";
 * const auth = defineBetterAuthService({
 *   baseURL: "http://127.0.0.1:3000",
 *   emailAndPassword: { enabled: true },
 * });
 * const handler = auth.handler;
 * ```
 * @category Services
 * @since 0.0.5
 */
export function defineBetterAuthService<const Options extends BetterAuthServiceOptions>(
  options: Options,
): BetterAuthServiceDescriptor<Options> {
  if (options === null || typeof options !== "object" || Array.isArray(options))
    throw new TypeError("Better Auth service options must be an object");
  if (Object.hasOwn(options, "database"))
    throw new TypeError("Better Auth service database is provided by the Drizzle service");
  if (Object.hasOwn(options, "basePath"))
    throw new TypeError("Better Auth basePath is derived from its ALL route");
  const runtime: BetterAuthRuntime<Options> = { options, activation: undefined };
  const handler = (async (request: Request) => {
    const owner = runtime.activation;
    if (owner === undefined) return new Response("Service Unavailable", { status: 503 });
    return runAuthPromise(
      owner,
      Effect.flatMap(AuthService, (auth) => auth.handler(request)),
      { signal: request.signal },
      "auth.handler",
    );
  }) as BetterAuthHandler<Auth<Options>["$Infer"]["Session"]>;
  const descriptor = {
    ...createDescriptorBase("service", createUnboundIdentity()),
    capability: Object.freeze({ kind: "better-auth" as const }),
    handler,
  };
  Object.defineProperty(handler, BETTER_AUTH_HANDLER, {
    value: Object.freeze({ kind: "better-auth", service: descriptor }),
  });
  Object.defineProperty(descriptor, BETTER_AUTH_RUNTIME, { value: runtime });
  Object.freeze(handler);
  return Object.freeze(descriptor) as BetterAuthServiceDescriptor<Options>;
}

"use client";

import { RelkitClientProvider } from "@relkit/client/react";
import { createElement, type ReactNode } from "react";
import type { BetterAuthRelkitClientProviderProps } from "./react.types.js";
export type { BetterAuthClientLike, BetterAuthRelkitClientProviderProps } from "./react.types.js";

/**
 * Remounts the RELKIT client whenever native authentication identity changes.
 * @typeParam Session - Session type inferred from the browser auth client.
 * @param props - Provider settings and a native useSession hook.
 * @returns React provider with pending authentication gated by a null identity.
 * @remarks Session id, update time and user id establish remount identity; errors
 * remain owned by the native hook. This browser entrypoint uses only client dependencies.
 * @example
 * ```ts
 * import { createElement } from "react";
 * import { createAuthClient } from "better-auth/react";
 * import { BetterAuthRelkitClientProvider } from "@relkit/better-auth/react";
 * const authClient = createAuthClient();
 * const provider = createElement(BetterAuthRelkitClientProvider, { authClient, children: null });
 * ```
 */
export function BetterAuthRelkitClientProvider<Session>(
  props: BetterAuthRelkitClientProviderProps<Session>,
): ReactNode {
  const { authClient, identityKey, ...providerProps } = props;
  const session = authClient.useSession();
  const key = session.isPending ? "pending" : sessionKey(session.data);
  return createElement(RelkitClientProvider, {
    ...providerProps,
    key,
    ...(session.isPending
      ? { identityKey: null }
      : identityKey === undefined
        ? {}
        : { identityKey }),
  });
}

/**
 * Derives React remount identity from the SDK's session/user fields.
 * @param value - Native session result, including absent/anonymous results.
 * @returns Stable identity key; native values remain opaque outside known fields.
 */
function sessionKey(value: unknown): string {
  if (value === null || value === undefined) return "anonymous";
  const session = record(record(value)?.session);
  const user = record(record(value)?.user);
  return [session?.id, session?.updatedAt, user?.id].map(String).join(":");
}

/**
 * Narrows opaque SDK records without coercing or serializing session values.
 * @param value - Candidate session or nested record.
 * @returns Record view when value is an object, otherwise undefined.
 */
function record(value: unknown): Readonly<Record<string, unknown>> | undefined {
  return value !== null && typeof value === "object"
    ? (value as Readonly<Record<string, unknown>>)
    : undefined;
}

import type { RelkitClientProviderProps } from "@relkit/client/react";

/**
 * Browser SDK hook contract retaining the native inferred session type.
 * @typeParam Session - Native client session and user result.
 */
export interface BetterAuthClientLike<Session> {
  /**
   * Reads reactive authentication state; hook ownership stays with React.
   * @returns Native session data, loading state and optional SDK error.
   */
  useSession(): {
    readonly data: Session | null | undefined;
    readonly isPending: boolean;
    readonly error?: unknown;
  };
}

/**
 * Client provider props with a native auth hook; no server runtime dependency.
 * @typeParam Session - Session result passed through the browser client hook.
 */
export interface BetterAuthRelkitClientProviderProps<Session> extends RelkitClientProviderProps {
  readonly authClient: BetterAuthClientLike<Session>;
}

/** Brands a stable route handler with its owning auth declaration. */
export const BETTER_AUTH_HANDLER = Symbol.for("relkit.better-auth.handler");

/** Stores server-only lazy activation state without exposing it publicly. */
