});
const activeInvocations = new Set();
let stopping = false;
${serverHttpSource(configuration)}
${SERVER_INVOCATION_SOURCE}
${SERVER_REGISTRATION_SOURCE}
${SERVER_NATIVE_WORKER_SOURCE}
${SERVER_RUNTIME_SOURCE}
${SERVER_SHUTDOWN_SOURCE}
`;
