 *
 * if (typeof Bun !== "undefined") {
 *   const { Database } = await import("bun:sqlite")
 *   const { drizzle } = await import("drizzle-orm/bun-sqlite")
 *   const users = sqliteTable("users", { id: integer().primaryKey() })
 *   const service = defineDrizzleService({
 *     schema: { users },
 *     client: () => drizzle({ client: new Database(":memory:") }),
 *     dispose: (database) => database.$client.close(),
 *   })
 *   const active = await activateDrizzleService(service, {})
 *   try { console.assert(active.context.users !== undefined) }
 *   finally { await active.close() }
 * }
 * ```
 * @category Database
 * @since 0.1.0
 */
export function activateDrizzleService<
  Service extends DrizzleServiceDescriptor<any, any, any, any>,
>(
  service: Service,
  env: Readonly<Record<string, unknown>>,
  options: DrizzleActivationOptions = {},
): Promise<DrizzleActivation<Service>> {
  if (options.isolated === true) return activate(service, env, options);
  const existing = activations.get(service);
  if (existing !== undefined) return existing;
  const activation = activate(service, env, options);
  activations.set(service, activation);
  activation.catch(() => activations.delete(service));
  return activation;
}

/**
 * Binds one native client and releases it if context construction fails.
 * @typeParam Service - Descriptor retaining client and model inference.
 * @param service - Lazy declaration to activate.
 * @param env - Resolved application environment.
 * @param options - Isolation and configured observation context.
 * @returns One native activation with shared close completion.
 */
async function activate<Service extends DrizzleServiceDescriptor<any, any, any, any>>(
  service: Service,
  env: Readonly<Record<string, unknown>>,
  options: DrizzleActivationOptions,
): Promise<DrizzleActivation<Service>> {
  const declaration = drizzleRuntimeOf(service);
  const instrumentation = Context.pick(
    References.CurrentLoggers,
    References.MinimumLogLevel,
    References.CurrentLogAnnotations,
    Metric.MetricRegistry,
    Metric.CurrentMetricAttributes,
    Tracer.Tracer,
    References.TracerEnabled,
    References.TracerTimingEnabled,
    Clock.Clock,
  )(options.instrumentation ?? Context.empty()).pipe(
    Context.add(
      Tracer.Tracer,
      specializedTracer(Context.get(options.instrumentation ?? Context.empty(), Tracer.Tracer)),
    ),
  );
  const runtime = ManagedRuntime.make(
    drizzleOwnerLayer(declaration, env).pipe(Layer.provide(Layer.succeedContext(instrumentation))),
  );
  const owner = await runDrizzlePromise(runtime, DrizzleOwner).catch(async (error: unknown) => {
    await runtime.dispose();
    throw error;
  });
  let result: DrizzleActivation<Service>;
  try {
    const context = createDatabaseContext(
      service,
      declaration,
      owner.client,
      (effect, operation, admitted) => {
        const work = inheritNativeLeases(admitted ? effect : withDrizzleWork(result, effect));
        return runSpecializedTrace(`database.${operation}`, () =>
          runDrizzlePromise(runtime, work.pipe(Effect.provideContext(instrumentation))),
        );
      },
    );
    let closing: Promise<void> | undefined;
    result = Object.freeze(
      Object.defineProperty(
        {
          client: owner.client,
          context,
          close: (): Promise<void> => {
            if (closing !== undefined) return closing;
            runtime.runSync(owner.beginClose());
            closing = (async () => {
              await runDrizzlePromise(runtime, owner.awaitDrained());
              const exit = await Effect.runPromiseExit(
                runtime.disposeEffect.pipe(Effect.provideContext(instrumentation)),
              );
              if (Exit.isFailure(exit)) throw squashDrizzleCause(exit.cause);
            })();
            return closing;
          },
        },
        Symbol.for("relkit.drizzle.service"),
        { value: service },
      ),
    ) as DrizzleActivation<Service>;
    owners.set(result, {
      service: owner,
      dialect: declaration.dialect,
      runtime,
      instrumentation,
      run: (effect) =>
        runDrizzlePromise(runtime, effect.pipe(Effect.provideContext(instrumentation))),
    });
  } catch (error) {
    try {
      await runtime.dispose();
    } catch (cleanup) {
      throw new AggregateError([error, cleanup], "Drizzle acquisition and cleanup failed");
    }
    throw error;
  }
  return result;
}

import type { Context } from "effect";
import type { DatabaseContext, DrizzleServiceDescriptor } from "./types.js";

/** Acquisition policy for an application that owns its database lifetime. */
export interface DrizzleActivationOptions {
  /** Bypasses descriptor sharing; the caller must close this activation. */
  readonly isolated?: boolean;
  /** Configured observation services captured by the compatibility owner. */
  readonly instrumentation?: Context.Context<never>;
}

/**
 * Frozen public activation; resource ownership ends at close.
 * @typeParam Service - Authored descriptor preserving native client/model inference.
 */
export interface DrizzleActivation<Service extends DrizzleServiceDescriptor<any, any, any, any>> {
  /** Native escape hatch; callers must use admitted APIs to guarantee orderly close. */
  readonly client: Service extends DrizzleServiceDescriptor<any, infer Client, any, any>
    ? Client
    : never;
  readonly context: DatabaseContext<Service>;
  /**
   * Stops admission and releases the owner after admitted native work settles.
   * @returns Shared close Promise; later calls observe the same completion.
   */
  readonly close: () => Promise<void>;
}

import { Effect } from "effect";
import { createBoundModel } from "./model.js";
import type { DrizzleServiceRuntime, ModelBinding } from "./runtime-types.js";
import type { DatabaseContext, DrizzleServiceDescriptor } from "./types.js";
import { nativeCall } from "./failure.js";
import { transactionEffect } from "./transaction.js";
import { observeSpecializedOperation } from "./operation-tracing.js";

import type { ContextRunner } from "./context.types.js";

/**
 * Constructs models without acquiring another client.
 * @typeParam Service - Public descriptor inference.
 * @param service - Database declaration.
 * @param runtime - Pure descriptor metadata.
 * @param database - Owned client.
 * @param run - Runtime execution and owner-admission edge.
 * @returns Frozen public models/schema/transaction context.
 * @see {@link activateDrizzleService} for the checked public owner lifecycle.
 */
export function createDatabaseContext<Service extends DrizzleServiceDescriptor<any, any, any, any>>(
  service: Service,
  runtime: DrizzleServiceRuntime,
  database: unknown,
  run: ContextRunner,
): DatabaseContext<Service> {
  return contextFor(service, runtime, database, false, run);
}

/**
 * Binds models to one database or active transaction.
 * @typeParam Service - Public descriptor inference.
 * @param service - Database declaration.
 * @param runtime - Metadata and extensions.
 * @param database - Transaction-aware native database.
 * @param inTransaction - Whether nesting is forbidden and parent admission is held.
 * @param execute - Owner execution boundary.
 * @returns Frozen context preserving public inference.
 */
function contextFor<Service extends DrizzleServiceDescriptor<any, any, any, any>>(
  service: Service,
  runtime: DrizzleServiceRuntime,
  database: unknown,
  inTransaction: boolean,
  execute: ContextRunner,
): DatabaseContext<Service> {
  const models: Record<string, object> = {};
  for (const tableName of Object.keys(runtime.tables)) {
    const binding: ModelBinding = Object.freeze({
      drizzle: database,
      run: (effect, operation, admitted) =>
        execute(effect, operation, inTransaction || admitted === true),
      table: runtime.tables[tableName]!,
      dialect: runtime.dialect,
      inTransaction,
      metadata: runtime.metadata[tableName]!,
      override: runtime.overrides[tableName] ?? {},
      schemas: runtime.effectSchemas[tableName]!,
    });
    models[tableName] = createBoundModel(binding, runtime.models[tableName]);
  }
  return Object.freeze({
    ...models,
    zodSchemas: runtime.zodSchemas,
    transaction: async <Value>(
      run: (context: DatabaseContext<Service>) => Value | Promise<Value>,
    ): Promise<Value> => {
      const operation = inTransaction
        ? nativeCall<Value>("transaction", () => {
            throw new TypeError("Nested portable transactions are not supported");
          })
        : transactionEffect(database, runtime.dialect, (transaction) =>
            Promise.resolve(run(contextFor(service, runtime, transaction, true, execute))),
          );
      return execute(
        observeSpecializedOperation("database.transaction", operation),
        "transaction",
        inTransaction,
      );
    },
  }) as DatabaseContext<Service>;
}

import type { Effect } from "effect";
import type { DrizzleFailure } from "./failure.js";

/**
 * Executes work at the existing owner edge; transaction children borrow their parent lease.
 * @typeParam A - Successful result.
 * @param effect - Lazy database work.
 * @param operation - Bounded tracing label.
 * @param admitted - True only while a parent already retains owner admission.
 * @returns Public Promise result or original native failure.
 */
export type ContextRunner = <A>(
  effect: Effect.Effect<A, DrizzleFailure>,
  operation: string,
  admitted?: boolean,
) => Promise<A>;

import { Effect } from "effect";
import { owners } from "./owner.js";
import { withSqlitePermit } from "./transaction.js";
import { DrizzleFailure } from "./failure.js";

/**
 * Coordinates raw specialized SDK work with portable SQLite operations.
 * @typeParam A - Result.
 * @typeParam E - Typed failure.
 * @typeParam R - Caller services.
 * @param activation - Exact borrowed database owner.
 * @param effect - Native work using nativeCall to retain active parent leases.
 * @returns Interruptible permit waiting followed by physical-client exclusion.
 * @remarks Native callbacks may reenter portable APIs while the parent lease is
 * active. Escaped callbacks must reacquire after that lease expires.
 */
export function withDrizzleSqliteWork<A, E, R>(activation: object, effect: Effect.Effect<A, E, R>) {
  return Effect.suspend(() => {
    const owner = owners.get(activation);
    if (owner === undefined)
      return Effect.fail(
        new DrizzleFailure({
          operation: "coordination",
          cause: new TypeError("Invalid Drizzle activation"),
        }),
      );
    return owner.dialect === "sqlite" ? withSqlitePermit(owner.service.client, effect) : effect;
  });
}

import { Cause, Effect, Exit, Schema } from "effect";
import type { ManagedRuntime } from "effect";
import { NativeLeases, runWithNativeLeases } from "./native-leases.js";

/** Expected native database, validation or owner-admission failure. */
export class DrizzleFailure extends Schema.TaggedError<DrizzleFailure>()("DrizzleFailure", {
  operation: Schema.String,
  cause: Schema.Defect(),
}) {}

/**
 * Suspends an uncancellable SDK call until actual completion.
 * @typeParam A - Native success value.
 * @param operation - Bounded diagnostic label.
 * @param run - Native call, invoked only during execution.
 * @returns A lazy typed effect; interruption waits for native settlement.
 * @remarks Drizzle's generic query contract has no AbortSignal parameter.
 * @see {@link runDrizzlePromise} for execution at the owning runtime boundary.
 */
export function nativeCall<A>(operation: string, run: () => A | PromiseLike<A>) {
  return Effect.uninterruptible(
    Effect.flatMap(NativeLeases, (leases) =>
      Effect.tryPromise({
        try: () => runWithNativeLeases(leases, () => Promise.resolve().then(run)),
        catch: (cause) => new DrizzleFailure({ operation, cause }),
      }),
    ),
  );
}

/**
 * Executes a compatibility edge retaining original native rejection identity.
 * @typeParam A - Success value.
 * @typeParam E - Operation failure.
 * @typeParam R - Owner services.
 * @typeParam ER - Layer acquisition failure.
 * @param runtime - Existing managed owner.
 * @param effect - Lazy operation.
 * @param options - Optional caller cancellation.
 * @returns The public result; mixed causes retain primary/cleanup reasons.
 * @example
 * ```ts
 * import { Effect, Layer, ManagedRuntime } from "effect";
 * import { runDrizzlePromise } from "@relkit/drizzle/internal";
 * const owner = ManagedRuntime.make(Layer.empty);
 * try { await runDrizzlePromise(owner, Effect.succeed(1)); }
 * finally { await owner.dispose(); }
 * ```
 */
export async function runDrizzlePromise<A, E, R, ER>(
  runtime: ManagedRuntime.ManagedRuntime<R, ER>,
  effect: Effect.Effect<A, E, R>,
  options?: Effect.RunOptions,
): Promise<A> {
  const exit = await runtime.runPromiseExit(effect, options);
  if (Exit.isSuccess(exit)) return exit.value;
  throw squashDrizzleCause(exit.cause);
}

/**
 * Translates one native failure without erasing mixed cleanup/interruption causes.
 * @typeParam E - Internal typed failure.
 * @param cause - Authoritative Effect cause.
 * @returns The original lone rejection, or an AggregateError retaining all reasons.
 */
export function squashDrizzleCause<E>(cause: Cause.Cause<E>): unknown {
  const translated = Cause.map(cause, (error) =>
    error instanceof DrizzleFailure ? error.cause : error,
  );
  if (translated.reasons.length <= 1) return Cause.squash(translated);
  const errors = translated.reasons.map((reason) =>
    reason._tag === "Fail"
      ? reason.error
      : reason._tag === "Die"
        ? reason.defect
        : new Error("Drizzle work interrupted"),
  );
  return new AggregateError(errors, "Drizzle work and cleanup failed", { cause: translated });
}

/**
 * Server-only runtime ownership, typed failures and borrowed-work composition.
 * @packageDocumentation
 */
export { activateDrizzleService, type DrizzleActivation } from "./activation.js";
export { drizzleRuntimeOf } from "./service.js";
export type { DrizzleServiceDescriptor } from "./types.js";
export { DrizzleFailure, nativeCall, runDrizzlePromise, squashDrizzleCause } from "./failure.js";
export {
  DrizzleOwner,
  drizzleOwnerLayer,
  withDrizzleWork,
  drizzleInstrumentationOf,
  runDrizzleWorkPromise,
} from "./owner.js";
export { observeSpecializedOperation, runSpecializedTrace } from "./operation-tracing.js";
export type { DrizzleOwnerInterface } from "./owner.types.js";
export { operationEffect } from "./operations.js";
export { withDrizzleSqliteWork } from "./coordination.js";
export { inheritNativeLeases } from "./native-leases.js";
export { redactSpecializedTrace } from "./trace-redaction.js";

import { getTableColumns, is, type Table } from "drizzle-orm";
import { getTableConfig as getMySqlTableConfig, MySqlTable } from "drizzle-orm/mysql-core";
import { getTableConfig as getPgTableConfig, PgTable } from "drizzle-orm/pg-core";
import { getTableConfig as getSqliteTableConfig, SQLiteTable } from "drizzle-orm/sqlite-core";
import type { TableMetadata } from "./runtime-types.js";
import type { TableMap } from "./types.js";

/**
 * Discovers one consistent dialect and unique table selectors.
 * @param tables - Authored table map.
 * @returns Pure dialect and frozen per-table metadata.
 * @throws TypeError for absent tables or mixed/unsupported dialects.
 */
export function inspectTables(tables: TableMap): {
  readonly dialect: "pg" | "mysql" | "sqlite";
  readonly metadata: Readonly<Record<string, TableMetadata>>;
} {
  const entries = Object.entries(tables);
  if (entries.length === 0) throw new TypeError("A data model requires at least one table");
  const dialects = new Set(entries.map(([, table]) => dialectFor(table)));
  if (dialects.size !== 1) throw new TypeError("A data model cannot mix Drizzle dialects");
  return {
    dialect: [...dialects][0]!,
    metadata: Object.freeze(
      Object.fromEntries(entries.map(([name, table]) => [name, tableMetadata(table)])),
    ),
  };
}

/**
 * Filters relations and other schema values from supported tables.
 * @param schema - Authored Drizzle schema.
 * @returns Frozen table-only map; no native client is acquired.
 * @throws TypeError when no supported table exists.
 */
export function extractTables(schema: Readonly<Record<string, unknown>>): TableMap {
  const tables = Object.fromEntries(
    Object.entries(schema).filter(([, value]) => isSupportedTable(value)),
  ) as TableMap;
  if (Object.keys(tables).length === 0) throw new TypeError("A Drizzle service requires a table");
  return Object.freeze(tables);
}

/**
 * Resolves a supported table dialect using Drizzle's entity guards.
 * @param table - Table to inspect.
 * @returns PostgreSQL, MySQL or SQLite dialect.
 * @throws TypeError for unsupported entities.
 */
export function dialectFor(table: Table): "pg" | "mysql" | "sqlite" {
  if (is(table, PgTable)) return "pg";
  if (is(table, MySqlTable)) return "mysql";
  if (is(table, SQLiteTable)) return "sqlite";
  throw new TypeError("Only PostgreSQL, MySQL, and SQLite Drizzle tables are supported");
}

/**
 * Distinguishes supported tables from relation declarations.
 * @param value - Unknown schema entry.
 * @returns Whether this integration supports its dialect.
 */
function isSupportedTable(value: unknown): value is Table {
  try {
    dialectFor(value as Table);
    return true;
  } catch {
    return false;
  }
}

/**
 * Collects declared columns and complete primary/unique selectors.
 * @param table - Supported table.
 * @returns Metadata keyed by authored names, preserving composite constraints.
 */
function tableMetadata(table: Table): TableMetadata {
  const columns = getTableColumns(table) as unknown as Record<string, unknown>;
  const config = configFor(table);
  const byColumn = new Map(Object.entries(columns).map(([name, column]) => [column, name]));
  const byDatabaseName = new Map(
    Object.entries(columns).map(([name, column]) => [
      (column as { readonly name?: unknown }).name,
      name,
    ]),
  );
  const selectors: string[][] = [];
  for (const [name, column] of Object.entries(columns)) {
    const metadata = column as { readonly primary?: unknown; readonly isUnique?: unknown };
    if (metadata.primary === true || metadata.isUnique === true) selectors.push([name]);
  }
  for (const constraint of [
    ...config.primaryKeys,
    ...config.uniqueConstraints,
    ...config.indexes,
  ]) {
    const record = constraint as {
      readonly columns?: readonly unknown[];
      readonly config?: unknown;
    };
    const index = isRecord(record.config) ? record.config : undefined;
    if (index !== undefined && index.unique !== true) continue;
    const names = (record.columns ?? (index?.columns as readonly unknown[] | undefined) ?? [])
      .map(
        (column) =>
          byColumn.get(column) ?? byDatabaseName.get((column as { readonly name?: unknown }).name),
      )
      .filter((name): name is string => name !== undefined);
    if (names.length > 0) selectors.push(names);
  }
  return {
    columns: Object.freeze({ ...columns }),
    selectors: Object.freeze(uniqueSelectors(selectors)),
  };
}

/**
 * Reads the driver's pure table configuration.
 * @param table - Supported table.
 * @returns Primary keys, unique constraints and indexes.
 * @throws TypeError for unsupported entities.
 */
function configFor(table: Table): {
  readonly primaryKeys: readonly unknown[];
  readonly uniqueConstraints: readonly unknown[];
  readonly indexes: readonly unknown[];
} {
  if (is(table, PgTable)) return getPgTableConfig(table);
  if (is(table, MySqlTable)) return getMySqlTableConfig(table);
  if (is(table, SQLiteTable)) return getSqliteTableConfig(table);
  throw new TypeError("Unsupported Drizzle table");
}

/**
 * Deduplicates equivalent selector sets without changing authored key order.
 * @param values - Discovered column-name combinations.
 * @returns Frozen unique selector arrays.
 */
function uniqueSelectors(values: readonly string[][]): readonly (readonly string[])[] {
  return [
    ...new Map(
      values.map((value) => [[...value].sort().join("\0"), Object.freeze([...value])]),
    ).values(),
  ];
}

/**
 * Checks optional index metadata records.
 * @param value - Unknown configuration value.
 * @returns Whether it is a non-array object.
 */
function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

import type { Table } from "drizzle-orm";
import { runOperation } from "./operations.js";
import { MODEL_RUNTIME, type ModelBinding, type ModelRuntime } from "./runtime-types.js";
import type {
  BaseOperations,
  ModelDescriptor,
  ModelDescriptorAny,
  ModelExtensionMap,
  NonEmptyExtensions,
} from "./types.js";
import { Effect } from "effect";
import { nativeCall } from "./failure.js";
import { observeSpecializedOperation } from "./operation-tracing.js";
import { withSqlitePermit } from "./transaction.js";

/** Reserved base operations; authored extensions may not shadow these names. */
export const RESERVED_OPERATIONS = Object.freeze([
  "findOne",
  "findMany",
  "insert",
  "update",
  "upsert",
  "delete",
] as const);

/**
 * Adds named table methods with an injected table and transaction-aware Drizzle client.
 * Use service overrides, not extensions, to replace the six reserved CRUD operations.
 * @typeParam T - Authored Drizzle table.
 * @typeParam Extensions - Inferred custom operation arguments and results.
 * @param options - Matching table and non-empty extension map.
 * @returns Frozen descriptor; extension functions remain lazy until activation use.
 * @throws TypeError for missing, non-callable or reserved extensions.
 *
 * @example
 * ```ts
 * import { defineModel } from "@relkit/drizzle"
 * import { integer, sqliteTable } from "drizzle-orm/sqlite-core"
 *
 * const users = sqliteTable("users", { id: integer().primaryKey() })
 * const model = defineModel({
 *   table: users,
 *   extend: { firstTen: ({ table, database }) => database.select().from(table).limit(10) },
 * })
 * console.assert(model.extensionNames.includes("firstTen"))
 * ```
 * @category Database
 * @since 0.1.0
 */
export function defineModel<
  const T extends Table,
  const Extensions extends ModelExtensionMap<T>,
>(options: {
  readonly table: T;
  readonly extend: NonEmptyExtensions<Extensions>;
}): ModelDescriptor<T, Extensions> {
  if (!isRecord(options) || !isRecord(options.extend) || Object.keys(options.extend).length === 0) {
    throw new TypeError("A model needs at least one extension function");
  }
  for (const [name, extension] of Object.entries(options.extend)) {
    if (RESERVED_OPERATIONS.includes(name as (typeof RESERVED_OPERATIONS)[number])) {
      throw new TypeError(`Model extensions cannot replace reserved operation "${name}"`);
    }
    if (typeof extension !== "function") {
      throw new TypeError(`Model extension "${name}" must be a function`);
    }
  }
  const runtime: ModelRuntime = { table: options.table, extend: options.extend as never };
  const descriptor = {
    table: options.table,
    extensionNames: Object.freeze(Object.keys(options.extend)),
  };
  Object.defineProperty(descriptor, MODEL_RUNTIME, { value: runtime });
  return Object.freeze(descriptor) as ModelDescriptor<T, Extensions>;
}

/**
 * Resolves hidden pure extension metadata.
 * @param value - Frozen model descriptor.
 * @returns Matching table and custom method definitions.
 * @throws TypeError for invalid descriptors.
 */
export function modelRuntimeOf(value: ModelDescriptorAny): ModelRuntime {
  const runtime = (value as unknown as Record<PropertyKey, unknown>)[MODEL_RUNTIME];
  if (!isRecord(runtime) || !isRecord(runtime.extend)) {
    throw new TypeError("Invalid Drizzle model descriptor");
  }
  return runtime as unknown as ModelRuntime;
}

/**
 * Binds public Promise methods to the owning Effect workflows.
 * @param binding - Client/schema/override metadata and execution edge.
 * @param model - Optional authored extensions.
 * @returns Frozen CRUD/custom methods preserving injected native dependencies.
 */
export function createBoundModel(binding: ModelBinding, model?: ModelDescriptorAny): object {
  const base: BaseOperations<Table> = {
    findOne: (args) => runOperation(binding, "findOne", args) as never,
    findMany: (args = {}) => runOperation(binding, "findMany", args) as never,
    insert: (args) => runOperation(binding, "insert", args) as never,
    update: (args) => runOperation(binding, "update", args) as never,
    upsert: (args) => runOperation(binding, "upsert", args) as never,
    delete: (args) => runOperation(binding, "delete", args) as never,
  };
  if (model === undefined) return Object.freeze(base);
  const extensions = Object.fromEntries(
    Object.entries(modelRuntimeOf(model).extend).map(([name, extension]) => [
      name,
      (...args: unknown[]) =>
        binding.run(
          observeSpecializedOperation(
            "database.extension",
            extensionEffect(binding, () =>
              extension({ table: binding.table, database: binding.drizzle as never }, ...args),
            ),
          ),
          "extension",
        ),
    ]),
  );
  return Object.freeze({ ...base, ...extensions });
}

/**
 * Executes an opaque user extension until native Promise completion.
 * @param binding - Table/client transaction coordination policy.
 * @param run - Extension thunk with transaction-aware dependencies.
 * @returns Lazy result or typed extension failure; inputs/results stay private.
 */
const extensionEffect = Effect.fn("Drizzle.extension")((
  binding: ModelBinding,
  run: () => unknown,
) => {
  const effect = nativeCall("extension", run);
  return binding.dialect === "sqlite" && !binding.inTransaction
    ? withSqlitePermit(binding.drizzle, effect)
    : effect;
});

/**
 * Checks opaque model declarations without invoking extensions.
 * @param value - Unknown declaration.
 * @returns Whether value is a non-array object.
 */
function isRecord(value: unknown): value is Record<PropertyKey, any> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

import { Effect } from "effect";
import type { ModelBinding } from "./runtime-types.js";
import { nativeCall } from "./failure.js";
import { decodeTableValue } from "./table.schemas.js";
import { checked, findOne, rows } from "./queries.js";
import { call, clause, hasMethod, record, recoverable, requiredRow } from "./operations.utils.js";

/**
 * Inserts one row, recovering MySQL rows via a declared unique key.
 * @param binding - Table/client metadata.
 * @param data - Unknown insert payload.
 * @returns Lazy inserted row; validation occurs before mutation.
 */
export const insert = Effect.fn("Drizzle.insert")((binding: ModelBinding, data: unknown) =>
  Effect.gen(function* () {
    const values = yield* decodeTableValue(binding.schemas.insert, data);
    const query = yield* checked(() =>
      call(call(binding.drizzle, "insert", binding.table), "values", values),
    );
    if (hasMethod(query, "returning")) {
      const selected = yield* rows(binding, yield* checked(() => call(query, "returning")));
      return yield* checked(() => requiredRow(selected[0]));
    }
    const where = yield* checked(() => {
      const key = recoverable(binding, record(values));
      if (key === undefined)
        throw new TypeError("MySQL insert requires a recoverable unique key override");
      return key;
    });
    yield* nativeCall("insert", () => query as PromiseLike<unknown>);
    return yield* findOne(binding, where).pipe(
      Effect.flatMap((row) => checked(() => requiredRow(row))),
    );
  }),
);

/**
 * Updates one selected row with dialect-aware returning/recovery.
 * @param binding - Table/client metadata.
 * @param where - Complete unique selector.
 * @param data - Unknown partial update.
 * @returns Lazy updated row or null.
 */
export const update = Effect.fn("Drizzle.update")(
  (binding: ModelBinding, where: Record<string, unknown>, data: unknown) =>
    Effect.gen(function* () {
      const values = yield* decodeTableValue(binding.schemas.update, data);
      const before = binding.dialect === "mysql" ? yield* findOne(binding, where) : undefined;
      if (binding.dialect === "mysql" && before === null) return null;
      const query = yield* checked(() =>
        call(
          call(call(binding.drizzle, "update", binding.table), "set", values),
          "where",
          clause(binding, where),
        ),
      );
      if (hasMethod(query, "returning"))
        return (yield* rows(binding, yield* checked(() => call(query, "returning"))))[0] ?? null;
      yield* nativeCall("update", () => query as PromiseLike<unknown>);
      const recover = yield* checked(() =>
        recoverable(binding, { ...record(before), ...record(values) }),
      );
      if (recover === undefined)
        return yield* checked(() => {
          throw new TypeError("MySQL update requires a recoverable unique key override");
        });
      return yield* findOne(binding, recover);
    }),
);

/**
 * Deletes one row while preserving dialect return behavior.
 * @param binding - Table/client metadata.
 * @param where - Complete unique selector.
 * @returns Lazy deleted row or null.
 */
export const remove = Effect.fn("Drizzle.delete")(
  (binding: ModelBinding, where: Record<string, unknown>) =>
    Effect.gen(function* () {
      const before = yield* findOne(binding, where);
      if (before === null) return null;
      const query = yield* checked(() =>
        call(call(binding.drizzle, "delete", binding.table), "where", clause(binding, where)),
      );
      if (hasMethod(query, "returning"))
        return (yield* rows(binding, yield* checked(() => call(query, "returning"))))[0] ?? null;
      yield* nativeCall("delete", () => query as PromiseLike<unknown>);
      return before;
    }),
);

import { AsyncLocalStorage } from "node:async_hooks";
import { Context, Effect, Fiber, Latch, Ref } from "effect";
import type { NativeLease, NativeLeaseContext } from "./native-leases.types.js";

const storage = new AsyncLocalStorage<NativeLeaseContext>();

/** Effect-local owner/physical-client leases, absent for independent callers. */
export const NativeLeases = Context.Reference<NativeLeaseContext>("@relkit/drizzle/NativeLeases", {
  defaultValue: () => ({}),
});

/**
 * Carries active parent leases into a new native Promise execution edge.
 * @typeParam A - Success value.
 * @typeParam E - Failure.
 * @typeParam R - Required services.
 * @param effect - New caller work.
 * @returns Work retaining only the current native parent's ephemeral leases.
 */
export function inheritNativeLeases<A, E, R>(effect: Effect.Effect<A, E, R>) {
  // A Deferred can synchronously resume an unrelated Effect fiber inside native
  // ALS. That fiber's own Context is authoritative, not the ambient native store.
  const fiber = Fiber.getCurrent();
  const inherited =
    fiber === undefined ? storage.getStore() : Context.get(fiber.context, NativeLeases);
  return inherited === undefined
    ? effect
    : effect.pipe(Effect.provideService(NativeLeases, inherited));
}

/**
 * Makes native SDK callbacks inherit the currently retained Effect leases.
 * @typeParam A - Native result.
 * @param leases - Effect-owned ephemeral capabilities.
 * @param run - Native SDK thunk.
 * @returns Native completion, including asynchronous SDK callback descendants.
 */
export function runWithNativeLeases<A>(leases: NativeLeaseContext, run: () => A): A {
  return storage.run(leases, run);
}

/**
 * Creates an Effect-owned descendant lease.
 * @param key - Exact owner or physical-client identity.
 * @returns A live token with no retained descendants.
 */
export const makeNativeLease = Effect.fn("Drizzle.nativeLease")((key: object) =>
  Effect.gen(function* () {
    return {
      key,
      state: yield* Ref.make({ accepting: true, closing: false, borrowers: 0 }),
      drained: yield* Latch.make(true),
    };
  }),
);

/**
 * Retains a still-active parent token atomically.
 * @param lease - Parent token.
 * @returns Whether the caller now owns a descendant lease.
 */
export function retainNativeLease(lease: NativeLease) {
  return Effect.uninterruptible(
    Effect.gen(function* () {
      const retained = yield* Ref.modify(lease.state, (state) =>
        state.accepting ? [true, { ...state, borrowers: state.borrowers + 1 }] : [false, state],
      );
      if (retained) yield* lease.drained.close;
      return retained;
    }),
  );
}

/**
 * Releases one retained descendant after safe native settlement.
 * @param lease - Retained parent token.
 * @returns Lazy release opening the parent's drain barrier when empty.
 */
export function releaseNativeLease(lease: NativeLease) {
  return Effect.uninterruptible(
    Effect.gen(function* () {
      const remaining = yield* Ref.modify(lease.state, (state) => [
        state.borrowers - 1,
        { ...state, borrowers: state.borrowers - 1 },
      ]);
      if (remaining === 0) yield* lease.drained.open;
    }),
  );
}

/**
 * Drains retained descendants, then atomically closes the token at zero.
 * @param lease - Owning token.
 * @returns Drain completion before the owning permit/admission may be released.
 */
export function closeNativeLease(lease: NativeLease) {
  return Effect.uninterruptible(
    Effect.gen(function* () {
      yield* Ref.update(lease.state, (state) => ({ ...state, closing: true }));
      // Retained children may invoke further native hooks before they settle.
      // Closing only at zero preserves that transitive capability without letting
      // any escaped callback enter after the owning scope actually releases.
      while (
        !(yield* Ref.modify(lease.state, (state) =>
          state.borrowers === 0 ? [true, { ...state, accepting: false }] : [false, state],
        ))
      ) {
        yield* lease.drained.await;
        yield* Effect.yieldNow;
      }
    }),
  );
}

import type { Latch, Ref } from "effect";

/** Effect-owned ephemeral lease with a drain barrier for retained descendants. */
export interface NativeLease {
  readonly key: object;
  readonly state: Ref.Ref<{
    readonly accepting: boolean;
    readonly closing: boolean;
    readonly borrowers: number;
  }>;
  readonly drained: Latch.Latch;
}

/** Native transport for exact owner and physical client capabilities. */
export interface NativeLeaseContext {
  readonly owner?: NativeLease;
  readonly sqlite?: NativeLease;
}

import { observeExecution } from "@relkit/contracts/operation";
import { Effect } from "effect";
import { frameworkTrace } from "@relkit/invocation";
import { redactSpecializedTrace } from "./trace-redaction.js";

const operations = new Set([
  "database.acquire",
  "database.close",
  "database.findOne",
  "database.findMany",
  "database.insert",
  "database.update",
  "database.upsert",
  "database.delete",
  "database.transaction",
  "database.extension",
  "auth.acquire",
  "auth.handler",
  "auth.session",
  "auth.api",
  "auth.factory",
]);

/**
 * Observes specialized work once through the configured caller sinks.
 * @typeParam A - Successful value.
 * @typeParam E - Typed failure retained together with defects/interruption.
 * @typeParam R - Required caller services.
 * @param operation - Bounded label; custom method names are normalized.
 * @param effect - Lazy authoritative work; payloads are never recorded.
 * @returns An observed Effect retaining values, causes and requirements.
 * @example
 * ```ts
 * import { Effect } from "effect";
 * import { observeSpecializedOperation } from "@relkit/drizzle/internal";
 * await Effect.runPromise(observeSpecializedOperation("auth.session", Effect.succeed(null)));
 * ```
 */
export function observeSpecializedOperation<A, E, R>(
  operation: `database.${string}` | `auth.${string}`,
  effect: Effect.Effect<A, E, R>,
): Effect.Effect<A, E, R> {
  const label = operations.has(operation)
    ? operation
    : operation.startsWith("database.")
      ? "database.extension"
      : "auth.api";
  return redactSpecializedTrace(
    observeExecution("runtime", label, effect, () => ({ operations: 1 })).pipe(
      Effect.withSpan(`relkit.${label}`),
    ),
  );
}

/**
 * Bridges invocation parenting without capturing native rows or auth sessions.
 * @typeParam A - Private operation result.
 * @param operation - Bounded operation label.
 * @param run - Existing runtime boundary.
 * @returns Original result; the invocation span sees only void.
 */
export async function runSpecializedTrace<A>(operation: string, run: () => Promise<A>): Promise<A> {
  let result: { readonly value: A } | undefined;
  let failure: { readonly cause: unknown } | undefined;
  try {
    await frameworkTrace.span(`relkit.${operation}`, {}, async () => {
      try {
        result = { value: await run() };
      } catch (cause) {
        failure = { cause };
        // Native SDK messages may include SQL, tokens or row values. Preserve
        // the native rejection privately while tracing only bounded failure text.
        throw new Error("Specialized operation failed");
      }
    });
  } catch (cause) {
    throw failure === undefined ? cause : failure.cause;
  }
  if (result === undefined) throw new TypeError("Specialized operation did not complete");
  return result.value;
}

import { Effect } from "effect";
import type { ModelBinding } from "./runtime-types.js";
import { nativeCall, type DrizzleFailure } from "./failure.js";
import { observeSpecializedOperation } from "./operation-tracing.js";
import { transactionEffect, withSqlitePermit } from "./transaction.js";
import { checked, findOne, findMany } from "./queries.js";
import { insert, update, remove } from "./mutations.js";
import { isRecord, requiredRow, selector } from "./operations.utils.js";

/**
 * Runs one lazy CRUD workflow at its compatibility edge.
 * @param binding - Owned client/model/transaction binding.
 * @param name - Reserved CRUD operation.
 * @param args - Public arguments validated inside the workflow.
 * @returns Native Promise result retaining expected native rejection identity.
 */
export function runOperation(binding: ModelBinding, name: string, args: unknown): Promise<unknown> {
  return binding.run(
    observeSpecializedOperation(`database.${name}`, operationEffect(binding, name, args)),
    name,
  );
}

/**
 * Composes overrides and MySQL write/recovery transaction ownership.
 * @param binding - Model binding.
 * @param name - Reserved operation.
 * @param args - Original override arguments.
 * @returns Lazy CRUD work with typed failures and no automatic write retries.
 * @example Compose a page with an existing owner and table binding
 * ```ts
 * import { Effect } from "effect";
 * import type { ManagedRuntime } from "effect";
 * import { DrizzleFailure, DrizzleOwner, operationEffect, runDrizzlePromise } from "@relkit/drizzle/internal";
 * function page(owner: ManagedRuntime.ManagedRuntime<DrizzleOwner, DrizzleFailure>, binding: Parameters<typeof operationEffect>[0]) {
 *   return runDrizzlePromise(owner, Effect.gen(function* () {
 *     const service = yield* DrizzleOwner;
 *     return yield* service.work(operationEffect(binding, "findMany", { limit: 10 }));
 *   }));
 * }
 * ```
 */
export const operationEffect = Effect.fn("Drizzle.operation")((
  binding: ModelBinding,
  name: string,
  args: unknown,
): Effect.Effect<unknown, DrizzleFailure> => {
  if (
    binding.dialect === "mysql" &&
    !binding.inTransaction &&
    ["insert", "update", "upsert", "delete"].includes(name)
  ) {
    return transactionEffect(binding.drizzle, "mysql", (drizzle) =>
      binding.run(
        operationEffect({ ...binding, drizzle, inTransaction: true }, name, args),
        name,
        true,
      ),
    );
  }
  const override = binding.override[name];
  const base = (next: unknown) => binding.run(baseOperation(binding, name, next), name, true);
  const effect =
    typeof override === "function"
      ? nativeCall(name, () => override({ args, base }))
      : baseOperation(binding, name, args);
  return binding.dialect === "sqlite" && !binding.inTransaction
    ? withSqlitePermit(binding.drizzle, effect)
    : effect;
});

/**
 * Dispatches validated arguments to named domain workflows.
 * @param binding - Table/client metadata.
 * @param name - Reserved operation.
 * @param args - Unknown public arguments.
 * @returns Lazy operation result or typed validation failure.
 */
function baseOperation(
  binding: ModelBinding,
  name: string,
  args: unknown,
): Effect.Effect<unknown, DrizzleFailure> {
  return Effect.gen(function* () {
    const value = isRecord(args) ? args : {};
    const where = () => selector(binding, value.where);
    switch (name) {
      case "findOne":
        return yield* findOne(binding, yield* checked(where));
      case "findMany":
        return yield* findMany(binding, value);
      case "insert":
        return yield* insert(binding, value.data);
      case "update":
        return yield* update(binding, yield* checked(where), value.data);
      case "delete":
        return yield* remove(binding, yield* checked(where));
      case "upsert": {
        const selected = yield* checked(where);
        const existing = yield* findOne(binding, selected);
        return existing === null
          ? yield* insert(binding, value.create)
          : yield* update(binding, selected, value.update).pipe(
              Effect.flatMap((row) => checked(() => requiredRow(row))),
            );
      }
      default:
        return yield* checked(() => {
          throw new TypeError(`Unknown model operation "${name}"`);
        });
    }
  });
}

import type { InferInsertModel, InferSelectModel, Table } from "drizzle-orm";

/**
 * Persisted row inferred from a table.
 * @typeParam T - Authored table.
 */
export type Row<T extends Table> = InferSelectModel<T>;

/**
 * Insert values retaining nullable, default and generated-column inference.
 * @typeParam T - Authored table.
 */
export type Insert<T extends Table> = InferInsertModel<T>;

/**
 * Partial insert-compatible update values.
 * @typeParam T - Authored table.
 */
export type Update<T extends Table> = Partial<Insert<T>>;

/**
 * Column equality filter; unique operations require a complete selector.
 * @typeParam T - Authored table.
 */
export type Where<T extends Table> = Partial<Row<T>>;

/**
 * Complete unique selector for one row.
 * @typeParam T - Authored table.
 */
export interface FindOneArgs<T extends Table> {
  readonly where: Where<T>;
}

/**
 * Bounded ordered page filters; default limit is 100.
 * @typeParam T - Authored table.
 */
export interface FindManyArgs<T extends Table> {
  readonly where?: Where<T>;
  readonly orderBy?: {
    readonly field: Extract<keyof Row<T>, string>;
    readonly direction: "asc" | "desc";
  };
  readonly limit?: number;
  readonly offset?: number;
}

/**
 * Single-row insertion values.
 * @typeParam T - Authored table.
 */
export interface InsertArgs<T extends Table> {
  readonly data: Insert<T>;
}

/**
 * Complete selector and partial update values.
 * @typeParam T - Authored table.
 */
export interface UpdateArgs<T extends Table> {
  readonly where: Where<T>;
  readonly data: Update<T>;
}

/**
 * Selector and separate create/update branches.
 * @typeParam T - Authored table.
 */
export interface UpsertArgs<T extends Table> {
  readonly where: Where<T>;
  readonly create: Insert<T>;
  readonly update: Update<T>;
}

/**
 * Complete unique selector for deletion.
 * @typeParam T - Authored table.
 */
export interface DeleteArgs<T extends Table> {
  readonly where: Where<T>;
}

/**
 * Stable public Promise CRUD contract over one table.
 * @typeParam T - Authored table.
 */
export interface BaseOperations<T extends Table> {
  /**
   * Selects one row by a complete unique key.
   * @param args - Unique selector.
   * @returns Matching row or null, rejecting invalid selectors/native failures.
   */
  findOne(args: FindOneArgs<T>): Promise<Row<T> | null>;

  /**
   * Selects a bounded ordered page.
   * @param args - Optional filters, ordering and pagination.
   * @returns Validated rows in driver order.
   */
  findMany(args?: FindManyArgs<T>): Promise<Row<T>[]>;

  /**
   * Inserts one row without automatic retries.
   * @param args - Insert values.
   * @returns Validated inserted row.
   */
  insert(args: InsertArgs<T>): Promise<Row<T>>;

  /**
   * Updates one selected row without automatic retries.
   * @param args - Unique selector and partial update values.
   * @returns Updated row or null when absent.
   */
  update(args: UpdateArgs<T>): Promise<Row<T> | null>;

  /**
   * Selects then inserts or updates using portable dialect semantics.
   * @param args - Unique selector and create/update branches.
   * @returns Resulting row; this portable read/write sequence is not an atomic SQL upsert.
   */
  upsert(args: UpsertArgs<T>): Promise<Row<T>>;

  /**
   * Removes one selected row without automatic retries.
   * @param args - Complete unique selector.
   * @returns Deleted row or null when absent.
   */
  delete(args: DeleteArgs<T>): Promise<Row<T> | null>;
}

import { and, eq, isNull, type Column, type SQL } from "drizzle-orm";
import type { ModelBinding } from "./runtime-types.js";

/**
 * Requires a complete non-null unique selector.
 * @param binding - Table metadata.
 * @param value - Unknown selector.
 * @returns Validated selector record.
 * @throws TypeError for invalid keys or incomplete uniqueness.
 */
export function selector(binding: ModelBinding, value: unknown): Record<string, unknown> {
  const where = record(value);
  for (const [key, entry] of Object.entries(where)) {
    columnFor(binding, key);
    if (entry === null || entry === undefined)
      throw new TypeError("Selector values cannot be null or undefined");
  }
  if (!binding.metadata.selectors.some((keys) => keys.every((key) => Object.hasOwn(where, key)))) {
    throw new TypeError("Selector must contain a complete primary or unique constraint");
  }
  return where;
}

/**
 * Finds a complete key for MySQL row recovery after writes.
 * @param binding - Table constraints.
 * @param value - Known row/write fields.
 * @returns One complete selector or undefined.
 */
export function recoverable(
  binding: ModelBinding,
  value: Record<string, unknown>,
): Record<string, unknown> | undefined {
  const keys = binding.metadata.selectors.find((candidate) =>
    candidate.every((key) => value[key] !== null && value[key] !== undefined),
  );
  return keys === undefined ? undefined : Object.fromEntries(keys.map((key) => [key, value[key]]));
}

/**
 * Builds equality predicates, treating null as SQL IS NULL.
 * @param binding - Declared columns.
 * @param where - Filter record.
 * @returns Conjoined predicate, or undefined for an empty filter.
 * @throws TypeError for undefined values or unknown columns.
 */
export function clause(binding: ModelBinding, where: Record<string, unknown>): SQL | undefined {
  const filters = Object.entries(where).map(([key, value]) => {
    const column = columnFor(binding, key);
    if (value === undefined) throw new TypeError("Filter values cannot be undefined");
    return value === null ? isNull(column) : eq(column, value);
  });
  return filters.length === 0 ? undefined : and(...filters);
}

/**
 * Resolves one declared column.
 * @param binding - Declared columns.
 * @param key - TypeScript column name.
 * @returns Drizzle column.
 * @throws TypeError for unknown fields.
 */
export function columnFor(binding: ModelBinding, key: string): Column {
  const column = binding.metadata.columns[key];
  if (column === undefined) throw new TypeError(`Unknown table column "${key}"`);
  return column as Column;
}

/**
 * Calls a checked native method with its original receiver.
 * @param target - Database or query builder.
 * @param name - Native method name.
 * @param args - Native arguments.
 * @returns Native method result, preserving thenables.
 * @throws TypeError when the method is unavailable.
 */
export function call(target: unknown, name: string, ...args: unknown[]): unknown {
  if (!isRecord(target) && typeof target !== "function")
    throw new TypeError(`Drizzle ${name} is unavailable`);
  const method = (target as Record<string, unknown>)[name];
  if (typeof method !== "function") throw new TypeError(`Drizzle ${name} is unavailable`);
  return method.apply(target, args);
}

/**
 * Inspects a native capability without invoking it.
 * @param target - Native builder.
 * @param name - Method name.
 * @returns Whether a callable method exists.
 */
export function hasMethod(target: unknown, name: string): boolean {
  return (
    (isRecord(target) || typeof target === "function") &&
    typeof (target as Record<string, unknown>)[name] === "function"
  );
}

/**
 * Requires a plain argument record.
 * @param value - Unknown arguments.
 * @returns Record retaining original keys.
 * @throws TypeError for null, arrays and scalar arguments.
 */
export function record(value: unknown): Record<string, unknown> {
  if (!isRecord(value)) throw new TypeError("Data-model arguments must be objects");
  return value;
}

/**
 * Checks bounded pagination without coercing strings.
 * @param value - Unknown limit/offset.
 * @param name - Diagnostic field.
 * @param fallback - Default when absent.
 * @param maximum - Inclusive maximum.
 * @returns Safe non-negative integer.
 * @throws TypeError for invalid pagination.
 */
export function integer(
  value: unknown,
  name: string,
  fallback: number,
  maximum = Number.MAX_SAFE_INTEGER,
): number {
  if (value === undefined) return fallback;
  if (!Number.isSafeInteger(value) || Number(value) < 0 || Number(value) > maximum)
    throw new TypeError(`${name} is invalid`);
  return Number(value);
}

/**
 * Requires a successful mutation row.
 * @param value - Native row or missing result.
 * @returns Existing row.
 * @throws TypeError when no row was returned.
 */
export function requiredRow(value: unknown): unknown {
  if (value === null || value === undefined) throw new TypeError("Mutation did not return a row");
  return value;
}

/**
 * Checks argument records without invoking getters.
 * @param value - Unknown value.
 * @returns Whether it is a non-array object.
 */
export function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

import { Context, Effect, Latch, Layer, Ref } from "effect";
import { DrizzleFailure, nativeCall } from "./failure.js";
import type { DrizzleServiceRuntime } from "./runtime-types.js";
import type { DrizzleOwnerInterface, OwnerBinding } from "./owner.types.js";
import { observeSpecializedOperation } from "./operation-tracing.js";
import { redactSpecializedTrace } from "./trace-redaction.js";
import {
  closeNativeLease,
  inheritNativeLeases,
  makeNativeLease,
  NativeLeases,
  releaseNativeLease,
  retainNativeLease,
} from "./native-leases.js";

/**
 * Client lifetime/admission contract, substitutable through live/test Layers.
 * @see {@link drizzleOwnerLayer} for checked acquisition/provisioning/cleanup composition.
 */
export class DrizzleOwner extends Context.Service<DrizzleOwner, DrizzleOwnerInterface>()(
  "@relkit/drizzle/Owner",
) {}

/** Weak association preserving the exact frozen public activation shape. */
export const owners = new WeakMap<object, OwnerBinding>();

/**
 * Acquires one client into a Layer scope.
 * @param declaration - Native acquisition/disposal dependencies.
 * @param env - First activation environment.
 * @returns A live owner Layer; its scope releases the client exactly once.
 * @example
 * ```ts
 * import { ManagedRuntime } from "effect";
 * import { sqliteTable, integer } from "drizzle-orm/sqlite-core";
 * import { defineDrizzleService } from "@relkit/drizzle";
 * import { DrizzleOwner, drizzleOwnerLayer, drizzleRuntimeOf } from "@relkit/drizzle/internal";
 * const records = sqliteTable("records", { id: integer().primaryKey() });
 * const declaration = drizzleRuntimeOf(defineDrizzleService({ schema: { records }, client: () => ({}) }));
 * const owner = ManagedRuntime.make(drizzleOwnerLayer(declaration, {}));
 * try { await owner.runPromise(DrizzleOwner); }
 * finally { await owner.dispose(); }
 * ```
 */
export function drizzleOwnerLayer(
  declaration: DrizzleServiceRuntime,
  env: Readonly<Record<string, unknown>>,
) {
  return Layer.effect(
    DrizzleOwner,
    redactSpecializedTrace(
      Effect.gen(function* () {
        // The release closure must also drain callers executing through a native
        // Effect context outside ManagedRuntime's own fiber scope.
        let service: DrizzleOwnerInterface | undefined;
        const client = yield* Effect.acquireRelease(
          observeSpecializedOperation(
            "database.acquire",
            nativeCall("acquire", () => declaration.client({ env })),
          ),
          (client) =>
            Effect.gen(function* () {
              if (service !== undefined) {
                yield* service.beginClose();
                yield* service.awaitDrained();
              }
              yield* observeSpecializedOperation(
                "database.close",
                nativeCall("close", () => declaration.dispose?.(client)),
              ).pipe(
                Effect.mapError((failure) => failure.cause),
                Effect.orDie,
              );
            }),
        );
        service = yield* makeDrizzleOwner(client);
        return service;
      }),
    ),
  );
}

/**
 * Creates the service contract for live acquisition or deterministic fake clients.
 * @param client - Client owned by the enclosing Layer scope.
 * @returns Lazy owner state and named admission/shutdown workflows.
 * @see {@link drizzleOwnerLayer} for the owning Layer and execution boundary.
 */
export const makeDrizzleOwner = Effect.fn("Drizzle.owner")((client: unknown) =>
  Effect.gen(function* () {
    const admission = yield* Ref.make({ closing: false, active: 0 });
    const drained = yield* Latch.make(true);
    return DrizzleOwner.of({
      client,
      admission,
      drained,
      work: <A, E, R>(effect: Effect.Effect<A, E, R>) =>
        redactSpecializedTrace(
          Effect.fn("Drizzle.admit")((work: Effect.Effect<A, E, R>) =>
            admitOwnerWork(admission, drained, work),
          )(effect),
        ),
      beginClose: Effect.fn("Drizzle.beginClose")(() =>
        Ref.update(admission, (state) => ({ ...state, closing: true })),
      ),
      awaitDrained: Effect.fn("Drizzle.awaitDrained")(() =>
        Effect.gen(function* () {
          // Atomic admission is authoritative; scheduler yielding can expose the
          // short interval between a count transition and its latch transition.
          while ((yield* Ref.get(admission)).active !== 0) {
            yield* drained.await;
            yield* Effect.yieldNow;
          }
        }),
      ),
    });
  }),
);

/**
 * Admits lazy work and releases its lease after safe native settlement.
 * @typeParam A - Success value.
 * @typeParam E - Caller failure.
 * @typeParam R - Caller services, retained without hidden provisioning.
 * @param activation - Frozen activation associated with its owner.
 * @param effect - Lazy work; SDK adapters must wait for native completion.
 * @returns The original effect with a typed closed-owner failure.
 * @example Compose work with an existing activation
 * ```ts
 * import { Effect } from "effect";
 * import { activateDrizzleService } from "@relkit/drizzle";
 * import { withDrizzleWork } from "@relkit/drizzle/internal";
 * function borrowedWork(active: Awaited<ReturnType<typeof activateDrizzleService>>) {
 *   return withDrizzleWork(active, Effect.succeed(1));
 * }
 * ```
 */
export function withDrizzleWork<A, E, R>(
  activation: object,
  effect: Effect.Effect<A, E, R>,
): Effect.Effect<A, E | DrizzleFailure, R> {
  return Effect.suspend(() => {
    const owner = owners.get(activation)?.service;
    if (owner === undefined)
      return Effect.fail(
        new DrizzleFailure({
          operation: "admission",
          cause: new TypeError("Invalid Drizzle activation"),
        }),
      );
    return owner.work(effect);
  });
}

/**
 * Owns the atomic admission/release transition for one caller.
 * @typeParam A - Success value.
 * @typeParam E - Caller failure.
 * @typeParam R - Caller services.
 * @param admission - Shared atomic owner state.
 * @param drained - Gate opened when all leases settle.
 * @param effect - Lazy caller work.
 * @returns Admitted effect or a typed closed-owner failure.
 */
function admitOwnerWork<A, E, R>(
  admission: DrizzleOwnerInterface["admission"],
  drained: Latch.Latch,
  effect: Effect.Effect<A, E, R>,
): Effect.Effect<A, E | DrizzleFailure, R> {
  return Effect.uninterruptibleMask((restore) =>
    Effect.gen(function* () {
      const leases = yield* NativeLeases;
      if (leases.owner?.key === admission && (yield* retainNativeLease(leases.owner)))
        return yield* restore(effect).pipe(Effect.ensuring(releaseNativeLease(leases.owner)));
      const admitted = yield* Ref.modify(admission, (state) =>
        state.closing ? [false, state] : [true, { ...state, active: state.active + 1 }],
      );
      if (!admitted)
        return yield* Effect.fail(
          new DrizzleFailure({
            operation: "admission",
            cause: new TypeError("Drizzle activation is closed"),
          }),
        );
      yield* drained.close;
      const lease = yield* makeNativeLease(admission);
      return yield* restore(effect).pipe(
        Effect.provideService(NativeLeases, { ...leases, owner: lease }),
        Effect.ensuring(
          Effect.gen(function* () {
            yield* closeNativeLease(lease);
            const remaining = yield* Ref.modify(admission, (state) => [
              state.active - 1,
              { ...state, active: state.active - 1 },
            ]);
            if (remaining === 0) yield* drained.open;
          }),
        ),
      );
    }),
  );
}

/**
 * Reads the observation context captured at activation.
 * @param activation - Database owner borrowed by another specialized service.
 * @returns Logger/tracer/metric context without additional client authority.
 */
export function drizzleInstrumentationOf(activation: object): Context.Context<never> {
  return owners.get(activation)?.instrumentation ?? Context.empty();
}

/**
 * Executes one admitted Promise compatibility edge.
 * @typeParam A - Success value.
 * @typeParam E - Operation failure.
 * @param activation - Database owner.
 * @param effect - Already instrumented lazy operation.
 * @returns Its public result, preserving native error identity.
 * @see {@link withDrizzleWork} for the equivalent Effect-native borrowed lease.
 */
export function runDrizzleWorkPromise<A, E>(
  activation: object,
  effect: Effect.Effect<A, E>,
): Promise<A> {
  const owner = owners.get(activation);
  if (owner === undefined) return Promise.reject(new TypeError("Invalid Drizzle activation"));
  return owner.run(inheritNativeLeases(withDrizzleWork(activation, effect)));
}

import type { Context, Effect, Latch, ManagedRuntime, Ref } from "effect";
import type { DrizzleFailure } from "./failure.js";
import type { DrizzleOwner } from "./owner.js";

/** Atomic owner admission state; close is monotonic. */
export interface AdmissionState {
  readonly closing: boolean;
  readonly active: number;
}

/** Shared live/test contract for one client lifetime. */
export interface DrizzleOwnerInterface {
  readonly client: unknown;
  readonly admission: Ref.Ref<AdmissionState>;
  readonly drained: Latch.Latch;

  /**
   * Admits lazy work while preserving its caller requirements and causes.
   * @typeParam A - Successful caller result.
   * @typeParam E - Caller typed failure.
   * @typeParam R - Required caller services.
   * @param effect - SDK adapter work retaining its lease until native settlement.
   * @returns Lazy caller work or a typed closed-owner admission failure.
   */
  readonly work: <A, E, R>(
    effect: Effect.Effect<A, E, R>,
  ) => Effect.Effect<A, E | DrizzleFailure, R>;

  /**
   * Marks admission closed monotonically.
   * @returns Lazy state transition; already admitted work retains its lease.
   */
  readonly beginClose: () => Effect.Effect<void>;

  /**
   * Awaits all previously admitted native work.
   * @returns Lazy drain barrier; resource disposal must follow this completion.
   */
  readonly awaitDrained: () => Effect.Effect<void>;
}

/** Private association; the public activation remains frozen. */
export interface OwnerBinding {
  readonly dialect: "sqlite" | "pg" | "mysql";
  readonly service: DrizzleOwnerInterface;
  readonly runtime: ManagedRuntime.ManagedRuntime<DrizzleOwner, DrizzleFailure>;
  readonly instrumentation: Context.Context<never>;
  readonly run: <A, E>(effect: Effect.Effect<A, E>) => Promise<A>;
}

import { asc, desc } from "drizzle-orm";
import { Effect } from "effect";
import type { ModelBinding } from "./runtime-types.js";
import { DrizzleFailure, nativeCall } from "./failure.js";
import { decodeTableValue } from "./table.schemas.js";
import { call, clause, columnFor, integer, record } from "./operations.utils.js";

/**
 * Selects one unique row and validates persisted data.
 * @param binding - Table/client metadata.
 * @param where - Complete unique selector.
 * @returns Lazy row or null when absent.
 */
export const findOne = Effect.fn("Drizzle.findOne")(
  (binding: ModelBinding, where: Record<string, unknown>) =>
    Effect.gen(function* () {
      const query = yield* checked(() =>
        call(
          call(
            call(call(binding.drizzle, "select"), "from", binding.table),
            "where",
            clause(binding, where),
          ),
          "limit",
          1,
        ),
      );
      const selected = yield* rows(binding, query);
      return selected[0] ?? null;
    }),
);

/**
 * Selects a bounded ordered page.
 * @param binding - Table/client metadata.
 * @param args - Filter/order/pagination arguments.
 * @returns Lazy validated rows in native ordering.
 */
export const findMany = Effect.fn("Drizzle.findMany")(
  (binding: ModelBinding, args: Record<string, unknown>) =>
    Effect.gen(function* () {
      const query = yield* checked(() => {
        const limit = integer(args.limit, "limit", 100, 1_000);
        const offset = integer(args.offset, "offset", 0);
        let query = call(call(binding.drizzle, "select"), "from", binding.table);
        if (args.where !== undefined)
          query = call(query, "where", clause(binding, record(args.where)));
        if (args.orderBy !== undefined) {
          const order = record(args.orderBy);
          if (typeof order.field !== "string" || order.field === "")
            throw new TypeError("orderBy.field is invalid");
          const column = columnFor(binding, order.field);
          if (order.direction !== "asc" && order.direction !== "desc")
            throw new TypeError("orderBy.direction must be asc or desc");
          query = call(query, "orderBy", order.direction === "asc" ? asc(column) : desc(column));
        }
        return call(call(query, "limit", limit), "offset", offset);
      });
      return yield* rows(binding, query);
    }),
);

/**
 * Awaits native rows then validates sequentially without starting new SDK work.
 * @param binding - Select schema.
 * @param query - Uncancellable native thenable.
 * @returns Lazy validated row array, preserving order and first failure.
 */
export function rows(binding: ModelBinding, query: unknown) {
  return Effect.gen(function* () {
    const value = yield* nativeCall("query", () => query as PromiseLike<unknown>);
    if (!Array.isArray(value))
      return yield* checked(() => {
        throw new TypeError("Drizzle query did not return rows");
      });
    return yield* Effect.forEach(value, (row) => decodeTableValue(binding.schemas.select, row));
  });
}

/**
 * Converts expected synchronous argument/native-builder exceptions.
 * @typeParam A - Result of pure/native-builder validation.
 * @param run - Suspended synchronous boundary.
 * @returns Lazy value or typed failure with original cause.
 */
export function checked<A>(run: () => A): Effect.Effect<A, DrizzleFailure> {
  return Effect.try({
    try: run,
    catch: (cause) => new DrizzleFailure({ operation: "validation", cause }),
  });
}

import type { Table } from "drizzle-orm";
import type { Effect } from "effect";
import type { DrizzleFailure } from "./failure.js";
import type { effectSchemasFor } from "./table.schemas.js";
import type { DrizzleModelMap, DrizzleOverrides, TableMap, TableZodSchemas } from "./types.js";

/** Stable hidden descriptor brand; shared across module copies. */
export const DRIZZLE_RUNTIME = Symbol.for("relkit.drizzle.runtime");

/** Stable hidden model descriptor brand. */
export const MODEL_RUNTIME = Symbol.for("relkit.drizzle.model.runtime");

/** Pure table-column and complete unique-selector metadata. */
export interface TableMetadata {
  readonly columns: Readonly<Record<string, unknown>>;
  readonly selectors: readonly (readonly string[])[];
}

/** Opaque authored extensions retaining their native injected database contract. */
export interface ModelRuntime {
  readonly table: Table;
  readonly extend: Readonly<Record<string, (context: any, ...args: any[]) => unknown>>;
}

/** Pure declaration dependencies; accessing this object never acquires a client. */
export interface DrizzleServiceRuntime {
  readonly client: (context: { readonly env: Readonly<Record<string, unknown>> }) => unknown;
  readonly dispose?: (database: any) => unknown;
  readonly schema: Readonly<Record<string, unknown>>;
  readonly tables: TableMap;
  readonly models: DrizzleModelMap<TableMap>;
  readonly overrides: DrizzleOverrides<TableMap>;
  readonly metadata: Readonly<Record<string, TableMetadata>>;
  readonly zodSchemas: Readonly<Record<string, TableZodSchemas<Table>>>;
  readonly effectSchemas: Readonly<Record<string, ReturnType<typeof effectSchemasFor>>>;
  readonly dialect: "pg" | "mysql" | "sqlite";
}

/** Table operations bound to an owner or an already admitted transaction. */
export interface ModelBinding {
  /**
   * Executes work at its owning runtime edge.
   * @typeParam A - Successful result.
   * @param effect - Lazy typed operation.
   * @param operation - Bounded diagnostic label.
   * @param admitted - Whether the caller already holds a parent lease.
   * @returns Public result or original native failure.
   */
  readonly run: <A>(
    effect: Effect.Effect<A, DrizzleFailure>,
    operation: string,
    admitted?: boolean,
  ) => Promise<A>;
  readonly drizzle: unknown;
  readonly table: Table;
  readonly dialect: "pg" | "mysql" | "sqlite";
  readonly inTransaction: boolean;
  readonly metadata: TableMetadata;
  readonly override: Readonly<Record<string, unknown>>;
  readonly schemas: ReturnType<typeof effectSchemasFor>;
}

import { createDescriptorBase } from "@relkit/contracts";
import { createUnboundIdentity } from "@relkit/invocation";
import { createInsertSchema, createSelectSchema, createUpdateSchema } from "drizzle-orm/zod";
import { getTableName } from "drizzle-orm";
import { extractTables, inspectTables } from "./metadata.js";
import { modelRuntimeOf, RESERVED_OPERATIONS } from "./model.js";
import { effectSchemasFor } from "./table.schemas.js";
import { DRIZZLE_RUNTIME, type DrizzleServiceRuntime } from "./runtime-types.js";
import type { DrizzleModelMap, DrizzleServiceDescriptor, TablesOf } from "./types.js";

import type { DefineDrizzleServiceOptions } from "./service.types.js";
export type { DefineDrizzleServiceOptions } from "./service.types.js";

/**
 * Defines the application's Drizzle service, table operations, and model customizations.
 * The client factory runs at activation, not during descriptor discovery.
 * @typeParam Client - Native driver client retained by activation.
 * @typeParam Schema - Authored tables and relations.
 * @typeParam Models - Table extensions preserving caller arguments/results.
 * @param options - Lazy client factory, schema, model/override and disposal policy.
 * @returns Frozen descriptor and pure capabilities; no SDK work is started.
 * @throws TypeError for invalid declarations, dialects, models or overrides.
 *
 * @example
 * ```ts
 * import { defineDrizzleService } from "@relkit/drizzle"
 * import { integer, sqliteTable } from "drizzle-orm/sqlite-core"
 *
 * const users = sqliteTable("users", { id: integer().primaryKey() })
 * const service = defineDrizzleService({
 *   schema: { users },
 *   client: () => { throw new Error("Configure a Drizzle driver before activation") },
 * })
 * console.assert(service.capability.dialect === "sqlite")
 * ```
 * @category Database
 * @since 0.1.0
 */
export function defineDrizzleService<
  Client,
  const Schema extends Readonly<Record<string, unknown>>,
  const Models extends DrizzleModelMap<TablesOf<Schema>> = {},
>(
  options: DefineDrizzleServiceOptions<Client, Schema, Models>,
): DrizzleServiceDescriptor<string, Client, Schema, Models> {
  if (!isRecord(options) || !isRecord(options.schema) || typeof options.client !== "function") {
    throw new TypeError("Invalid Drizzle service options");
  }
  const tables = extractTables(options.schema);
  const inspection = inspectTables(tables);
  const models = Object.freeze({ ...(options.models ?? {}) }) as Models;
  const overrides = Object.freeze({ ...(options.overrides ?? {}) });
  validateModels(tables, models);
  validateOverrides(tables, overrides, inspection.metadata);
  const zodSchemas = Object.freeze(
    Object.fromEntries(
      Object.entries(tables).map(([name, table]) => [
        name,
        Object.freeze({
          select: createSelectSchema(table),
          insert: createInsertSchema(table),
          update: createUpdateSchema(table),
        }),
      ]),
    ),
  );
  const runtime: DrizzleServiceRuntime = {
    client: options.client as DrizzleServiceRuntime["client"],
    ...(options.dispose === undefined ? {} : { dispose: options.dispose }),
    schema: options.schema,
    tables,
    models,
    overrides,
    metadata: inspection.metadata,
    zodSchemas,
    effectSchemas: Object.freeze(
      Object.fromEntries(
        Object.entries(tables).map(([name, table]) => [name, effectSchemasFor(table)]),
      ),
    ),
    dialect: inspection.dialect,
  };
  const capability = Object.freeze({
    kind: "drizzle" as const,
    dialect: inspection.dialect,
    tables: Object.freeze(
      Object.entries(tables).map(([name, table]) =>
        Object.freeze({
          name,
          databaseName: getTableName(table),
          columns: Object.freeze(
            Object.entries(inspection.metadata[name]!.columns).map(([key, column]) => {
              const value = column as Record<string, unknown>;
              return Object.freeze({
                key,
                name: typeof value.name === "string" ? value.name : key,
                dataType: typeof value.dataType === "string" ? value.dataType : "unknown",
                notNull: value.notNull === true,
                hasDefault: value.hasDefault === true,
                primaryKey: value.primary === true,
                unique: value.isUnique === true,
              });
            }),
          ),
          selectors: inspection.metadata[name]!.selectors,
          customMethods: capabilityMethods(models, name),
        }),
      ),
    ),
  });
  const descriptor = {
    ...createDescriptorBase("service", options.id ?? createUnboundIdentity()),
    capability,
  };
  Object.defineProperty(descriptor, DRIZZLE_RUNTIME, { value: runtime });
  return Object.freeze(descriptor) as DrizzleServiceDescriptor<string, Client, Schema, Models>;
}

/**
 * Reads the declared extension names for capability discovery.
 * @param models - Pure authored model map.
 * @param name - Schema table key.
 * @returns Frozen declared custom methods, or an empty list.
 */
function capabilityMethods(models: object, name: string): readonly string[] {
  const model = (models as Record<string, { readonly extensionNames?: readonly string[] }>)[name];
  return model?.extensionNames ?? Object.freeze([]);
}

/**
 * Resolves hidden runtime metadata without acquiring a client.
 * @param value - Frozen service declaration.
 * @returns Pure client factory/table metadata.
 * @throws TypeError for unbranded declarations.
 */
export function drizzleRuntimeOf(value: object): DrizzleServiceRuntime {
  const runtime = (value as Record<PropertyKey, unknown>)[DRIZZLE_RUNTIME];
  if (!isRecord(runtime)) throw new TypeError("Invalid Drizzle service descriptor");
  return runtime as unknown as DrizzleServiceRuntime;
}

/**
 * Validates extension table identity.
 * @param tables - Discovered tables.
 * @param models - Authored extensions.
 * @returns Void after validation.
 * @throws TypeError for unknown or mismatched tables.
 */
function validateModels(
  tables: Readonly<Record<string, unknown>>,
  models: Readonly<Record<string, unknown>>,
): void {
  for (const [name, model] of Object.entries(models)) {
    if (!(name in tables)) throw new TypeError(`Unknown Drizzle model table "${name}"`);
    const runtime = modelRuntimeOf(model as never);
    if (runtime.table !== tables[name]) {
      throw new TypeError(`Drizzle model "${name}" must use the matching schema table`);
    }
  }
}

/**
 * Checks override names and required keyless-table operations.
 * @param tables - Discovered tables.
 * @param overrides - Authored operation substitutions.
 * @param metadata - Discovered unique selectors.
 * @returns Void after validation.
 * @throws TypeError for invalid overrides or uncovered keyless operations.
 */
function validateOverrides(
  tables: Readonly<Record<string, unknown>>,
  overrides: Readonly<Record<string, any>>,
  metadata: DrizzleServiceRuntime["metadata"],
): void {
  for (const [name, value] of Object.entries(overrides)) {
    if (!(name in tables)) throw new TypeError(`Unknown Drizzle override table "${name}"`);
    for (const operation of Object.keys(value ?? {})) {
      if (!(RESERVED_OPERATIONS as readonly string[]).includes(operation)) {
        throw new TypeError(`Unknown base operation override "${operation}"`);
      }
    }
  }
  for (const [name, table] of Object.entries(metadata)) {
    if (table.selectors.length > 0) continue;
    const missing = ["findOne", "update", "upsert", "delete"].filter(
      (operation) => typeof overrides[name]?.[operation] !== "function",
    );
    if (missing.length > 0) {
      throw new TypeError(`Keyless table "${name}" requires overrides for ${missing.join(", ")}`);
    }
  }
}

/**
 * Narrows opaque declaration records without acquiring clients.
 * @param value - Unknown declaration.
 * @returns Whether value is a non-array object.
 */
function isRecord(value: unknown): value is Record<PropertyKey, any> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

import type { ApplicationEnv, DrizzleModelMap, DrizzleOverrides, TablesOf } from "./types.js";

/**
 * Lazy authoring options preserving native client and model extension inference.
 * @typeParam Client - Acquired native client type.
 * @typeParam Schema - Authored schema containing supported Drizzle tables.
 * @typeParam Models - Table-specific authored extensions.
 */
export interface DefineDrizzleServiceOptions<
  Client,
  Schema extends Readonly<Record<string, unknown>>,
  Models extends DrizzleModelMap<TablesOf<Schema>>,
> {
  readonly id?: string;
  readonly schema: Schema;
  /**
   * Acquires a native client when the owner Layer is first built.
   * @param context - First activation environment.
   * @returns Native client or acquisition Promise; failures retain native identity.
   */
  readonly client: (context: { readonly env: ApplicationEnv }) => Client | Promise<Client>;
  readonly models?: Models;
  readonly overrides?: DrizzleOverrides<TablesOf<Schema>>;
  /**
   * Releases the owned native client once admitted work has drained.
   * @param database - Successfully acquired client.
   * @returns Optional native completion; failure remains visible at close.
   */
  readonly dispose?: (database: Client) => unknown | Promise<unknown>;
}

import {
  createInsertSchema,
  createSelectSchema,
  createUpdateSchema,
} from "drizzle-orm/effect-schema";
import type { Table } from "drizzle-orm";
import { Effect, Schema } from "effect";
import { DrizzleFailure } from "./failure.js";

/**
 * Generates pinned Drizzle/Effect contracts without acquiring a database.
 * @param table - Declared table, retaining null/default/generated metadata.
 * @returns Select, insert and update schemas parallel to public Zod contracts.
 */
export function effectSchemasFor(table: Table) {
  return Object.freeze({
    select: createSelectSchema(table),
    insert: createInsertSchema(table),
    update: createUpdateSchema(table),
  });
}

/**
 * Validates unknown native rows or write data at the domain boundary.
 * @param schema - Generated table contract.
 * @param value - Unknown data; never included in telemetry.
 * @returns Lazy validated value or a typed validation failure.
 */
export function decodeTableValue(schema: Schema.Codec<unknown, unknown>, value: unknown) {
  return Schema.decodeUnknownEffect(schema)(value).pipe(
    Effect.mapError((cause) => new DrizzleFailure({ operation: "validation", cause })),
  );
}

import { Cause, Effect, Exit, Tracer } from "effect";

const tracers = new WeakMap<Tracer.Tracer, Tracer.Tracer>();

/**
 * Protects configured tracers without changing authoritative workflow exits.
 * @typeParam A - Private success value.
 * @typeParam E - Original failure.
 * @typeParam R - Caller services.
 * @param effect - Specialized workflow including its named descendant spans.
 * @returns Work using a tracer that receives only bounded diagnostic exits.
 */
export function redactSpecializedTrace<A, E, R>(effect: Effect.Effect<A, E, R>) {
  return Effect.flatMap(Tracer.Tracer, (tracer) =>
    effect.pipe(Effect.provideService(Tracer.Tracer, specializedTracer(tracer))),
  );
}

/**
 * Adapts span completion before an external exporter can inspect native causes.
 * @param tracer - Configured backend, retaining IDs, timing and parenting.
 * @returns Cached adapter; native success data and exception stacks stay private.
 */
export function specializedTracer(tracer: Tracer.Tracer): Tracer.Tracer {
  const existing = tracers.get(tracer);
  if (existing !== undefined) return existing;
  const protectedTracer = Tracer.make({
    ...(tracer.context === undefined ? {} : { context: tracer.context.bind(tracer) }),
    span(options) {
      const span = tracer.span(options);
      return new Proxy(span, {
        get(target, key) {
          if (key === "end")
            return (time: bigint, exit: Exit.Exit<unknown, unknown>) => {
              const diagnostic = Exit.isSuccess(exit)
                ? Exit.void
                : Exit.failCause(
                    Cause.fromReasons(
                      exit.cause.reasons.map((reason) =>
                        reason._tag === "Fail"
                          ? Cause.makeFailReason(new Error("Specialized operation failed"))
                          : reason._tag === "Die"
                            ? Cause.makeDieReason(new Error("Specialized operation defect"))
                            : Cause.makeInterruptReason(reason.fiberId),
                      ),
                    ),
                  );
              target.end(time, diagnostic);
            };
          const value = Reflect.get(target, key, target);
          return typeof value === "function" ? value.bind(target) : value;
        },
      });
    },
  });
  tracers.set(tracer, protectedTracer);
  tracers.set(protectedTracer, protectedTracer);
  return protectedTracer;
}

import { sql } from "drizzle-orm";
import { Cause, Effect, Exit, Semaphore } from "effect";
import { DrizzleFailure, nativeCall } from "./failure.js";
import {
  closeNativeLease,
  makeNativeLease,
  NativeLeases,
  releaseNativeLease,
  retainNativeLease,
} from "./native-leases.js";

const coordinators = new WeakMap<object, Semaphore.Semaphore>();

/**
 * Executes a portable transaction under the physical SQLite client lock.
 * @typeParam A - Callback result.
 * @param database - Native Drizzle wrapper.
 * @param dialect - Declared database dialect.
 * @param run - Callback using the actual transactional database.
 * @returns Lazy typed transaction work; native calls settle before lock release.
 */
export const transactionEffect = Effect.fn("Drizzle.transaction")(<A>(
  database: unknown,
  dialect: "pg" | "mysql" | "sqlite",
  run: (database: unknown) => Promise<A>,
) => {
  if (dialect !== "sqlite")
    return nativeCall("transaction", () => {
      const method = (database as { readonly transaction?: unknown }).transaction;
      if (typeof method !== "function") throw new TypeError("Drizzle transactions are unavailable");
      return method.call(database, run) as Promise<A>;
    });
  // Permit waiting is interruptible; once BEGIN starts no callback/driver promise
  // may outlive the protected transaction and race rollback or a new BEGIN.
  return withSqlitePermit(
    database,
    Effect.uninterruptible(
      Effect.gen(function* () {
        yield* runSql(database, "begin");
        const exit = yield* Effect.exit(
          Effect.gen(function* () {
            const value = yield* nativeCall("transaction", () => run(database));
            yield* runSql(database, "commit");
            return value;
          }),
        );
        if (Exit.isSuccess(exit)) return exit.value;
        const rollback = yield* Effect.exit(runSql(database, "rollback"));
        return yield* Effect.failCause(
          Exit.isFailure(rollback) ? Cause.combine(exit.cause, rollback.cause) : exit.cause,
        );
      }),
    ),
  );
});

/**
 * Serializes conflicting SQLite work at the physical client boundary.
 * @typeParam A - Success value.
 * @typeParam E - Caller failure.
 * @typeParam R - Caller services.
 * @param database - Native wrapper or physical client.
 * @param effect - Lazy work; native calls must settle before its lease ends.
 * @returns Interruptible permit waiting followed by protected work.
 * @remarks Transaction-bound children already hold the parent's permit and must
 * bypass this combinator. Weak keys permit collection when native owners expire.
 */
export function withSqlitePermit<A, E, R>(
  database: unknown,
  effect: Effect.Effect<A, E, R>,
): Effect.Effect<A, E | DrizzleFailure, R> {
  return Effect.flatMap(
    Effect.try({
      try: () => {
        if (database === null || (typeof database !== "object" && typeof database !== "function"))
          throw new TypeError("SQLite transactions are unavailable");
        const physical = (database as { readonly $client?: unknown }).$client;
        const key =
          physical !== null && (typeof physical === "object" || typeof physical === "function")
            ? physical
            : database;
        let semaphore = coordinators.get(key);
        if (semaphore === undefined) {
          semaphore = Semaphore.makeUnsafe(1);
          coordinators.set(key, semaphore);
        }
        return { semaphore, key };
      },
      catch: (cause) => new DrizzleFailure({ operation: "coordination", cause }),
    }),
    ({ semaphore, key }) =>
      Effect.flatMap(NativeLeases, (leases) => {
        const acquire = () =>
          semaphore.withPermit(
            Effect.flatMap(makeNativeLease(key), (lease) => {
              return effect.pipe(
                Effect.provideService(NativeLeases, { ...leases, sqlite: lease }),
                Effect.ensuring(closeNativeLease(lease)),
              );
            }),
          );
        const lease = leases.sqlite;
        if (lease?.key !== key) return acquire();
        return Effect.uninterruptibleMask((restore) =>
          Effect.gen(function* () {
            if (!(yield* retainNativeLease(lease))) return yield* restore(acquire());
            return yield* restore(effect).pipe(Effect.ensuring(releaseNativeLease(lease)));
          }),
        );
      }),
  );
}

/**
 * Runs native SQLite transaction control without assuming cancellation.
 * @param database - Drizzle wrapper exposing run.
 * @param statement - Fixed transaction control statement.
 * @returns Completion or original typed native failure.
 */
function runSql(database: unknown, statement: "begin" | "commit" | "rollback") {
  return nativeCall(statement, () => {
    const method = (database as { readonly run?: unknown }).run;
    if (typeof method !== "function") throw new TypeError("SQLite transactions are unavailable");
    return method.call(database, sql.raw(statement));
  });
}

import type { Row, Insert, Update, BaseOperations } from "./operations.types.js";
import type { DescriptorBase, MaybePromise } from "@relkit/contracts";
import type { MySqlAsyncDatabase, MySqlTable } from "drizzle-orm/mysql-core";
import type { PgAsyncDatabase, PgTable } from "drizzle-orm/pg-core";
import type { SQLiteAsyncDatabase, SQLiteTable } from "drizzle-orm/sqlite-core";
import type { Table } from "drizzle-orm";
import type { ZodType } from "zod";

/** Supported tables keyed by authored schema names. */
export type TableMap = Readonly<Record<string, Table>>;

/**
 * Table-only projection of an authored Drizzle schema.
 * @typeParam Schema - Authored table/relation map.
 */
export type TablesOf<Schema> = {
  readonly [Name in keyof Schema as Schema[Name] extends Table ? Name : never]: Extract<
    Schema[Name],
    Table
  >;
};

export type {
  Row,
  Insert,
  Update,
  Where,
  FindOneArgs,
  FindManyArgs,
  InsertArgs,
  UpdateArgs,
  UpsertArgs,
  DeleteArgs,
  BaseOperations,
} from "./operations.types.js";

/**
 * Native override receiving a Promise base operation.
 * @typeParam Args - Original validated public operation arguments.
 * @typeParam Result - Public operation result.
 * @param options - Caller arguments and lazy base operation on the same client.
 * @returns Authored synchronous or asynchronous replacement result.
 */
export type OperationOverride<Args, Result> = (options: {
  readonly args: Args;
  readonly base: (args: Args) => Promise<Result>;
}) => MaybePromise<Result>;

/**
 * Optional replacements for the six reserved table operations.
 * @typeParam T - Matching table.
 */
export type TableOverrides<T extends Table> = {
  readonly [Name in keyof BaseOperations<T>]?: OperationOverride<
    Parameters<BaseOperations<T>[Name]>[0],
    Awaited<ReturnType<BaseOperations<T>[Name]>>
  >;
};

/**
 * Table-keyed override declarations.
 * @typeParam Tables - Discovered table map.
 */
export type DrizzleOverrides<Tables extends TableMap> = {
  readonly [Name in keyof Tables]?: TableOverrides<Tables[Name]>;
};

/**
 * Transaction-aware native database surface inferred by dialect.
 * @typeParam T - Table declaring the native dialect.
 */
export type DialectDatabase<T extends Table> = T extends SQLiteTable
  ? Omit<SQLiteAsyncDatabase<any, any, any>, "query">
  : T extends PgTable
    ? Omit<PgAsyncDatabase<any, any>, "query">
    : T extends MySqlTable
      ? Omit<MySqlAsyncDatabase<any, any>, "query">
      : never;

/**
 * Injected table and transaction-bound native database.
 * @typeParam T - Matching table.
 */
export interface ModelExtensionContext<T extends Table> {
  readonly table: T;
  readonly database: DialectDatabase<T>;
}

/**
 * Authored native extension with inferred caller arguments/results.
 * @typeParam T - Matching authored table.
 * @param context - Table and transaction-aware native database.
 * @param args - Custom caller arguments preserved in the public context.
 * @returns Authored result whose exact synchronous/asynchronous type is retained.
 */
export type ModelExtension<T extends Table> = (
  context: ModelExtensionContext<T>,
  ...args: any[]
) => unknown;

/**
 * Named authored extension functions.
 * @typeParam T - Matching table.
 */
export type ModelExtensionMap<T extends Table> = Readonly<Record<string, ModelExtension<T>>>;

/**
 * Rejects declarations without any custom methods.
 * @typeParam Extensions - Authored method map.
 */
export type NonEmptyExtensions<Extensions extends Readonly<Record<string, unknown>>> =
  keyof Extensions extends never ? never : Extensions;

declare const MODEL_TYPES: unique symbol;

/**
 * Frozen lazy model descriptor retaining authored extension types.
 * @typeParam T - Matching table.
 * @typeParam Extensions - Inferred custom method signatures.
 */
export interface ModelDescriptor<
  T extends Table,
  Extensions extends ModelExtensionMap<T> = ModelExtensionMap<T>,
> {
  readonly table: T;
  readonly extensionNames: readonly Extract<keyof Extensions, string>[];
  readonly [MODEL_TYPES]: Extensions;
}

/** Internal erased model descriptor used for pure discovery. */
export type ModelDescriptorAny = ModelDescriptor<Table, ModelExtensionMap<Table>>;

/**
 * Optional table-keyed model declarations.
 * @typeParam Tables - Discovered table map.
 */
export type DrizzleModelMap<Tables extends TableMap> = Partial<{
  readonly [Name in keyof Tables]: ModelDescriptor<Tables[Name], any>;
}>;

/**
 * Projects authored methods without their injected context argument.
 * @typeParam Model - Lazy model descriptor.
 */
type ConsumerExtensions<Model> =
  Model extends ModelDescriptor<any, infer Extensions>
    ? {
        readonly [Name in keyof Extensions]: Extensions[Name] extends (
          context: any,
          ...args: infer Args
        ) => infer Result
          ? (...args: Args) => Result
          : never;
      }
    : {};

/**
 * Unchanged public select, insert and update Zod contracts.
 * @typeParam T - Matching table.
 */
export interface TableZodSchemas<T extends Table> {
  readonly select: ZodType<Row<T>>;
  readonly insert: ZodType<Insert<T>>;
  readonly update: ZodType<Update<T>>;
}

declare global {
  namespace Relkit {
    interface ApplicationEnv {}
  }
}

/** Application declaration augmentation, falling back to string environment values. */
export type ApplicationEnv = keyof Relkit.ApplicationEnv extends never
  ? Readonly<Record<string, string>>
  : Readonly<Relkit.ApplicationEnv>;

/** Pure compiler-visible dialect, tables, constraints and custom methods. */
export interface DrizzleCapability {
  readonly kind: "drizzle";
  readonly dialect: "pg" | "mysql" | "sqlite";
  readonly tables: readonly {
    readonly name: string;
    readonly databaseName: string;
    readonly columns: readonly {
      readonly key: string;
      readonly name: string;
      readonly dataType: string;
      readonly notNull: boolean;
      readonly hasDefault: boolean;
      readonly primaryKey: boolean;
      readonly unique: boolean;
    }[];
    readonly selectors: readonly (readonly string[])[];
    readonly customMethods: readonly string[];
  }[];
}

declare const SERVICE_TYPES: unique symbol;

/**
 * Frozen service descriptor retaining native client, schema and model inference.
 * @typeParam Id - Service identity.
 * @typeParam Client - Acquired native client.
 * @typeParam Schema - Authored schema.
 * @typeParam Models - Inferred table-specific models.
 */
export type DrizzleServiceDescriptor<
  Id extends string,
  Client,
  Schema,
  Models extends DrizzleModelMap<TablesOf<Schema>>,
> = DescriptorBase<"service", Id> & {
  readonly capability: DrizzleCapability;
  readonly [SERVICE_TYPES]: {
    readonly client: Client;
    readonly schema: Schema;
    readonly models: Models;
  };
};

/**
 * Public transaction-aware table operations and unchanged Zod schemas.
 * @typeParam Service - Authored service retaining table/model types.
 */
export type DatabaseContext<Service extends DrizzleServiceDescriptor<any, any, any, any>> = {
  readonly [Name in keyof TablesOf<Service[typeof SERVICE_TYPES]["schema"]>]: BaseOperations<
    TablesOf<Service[typeof SERVICE_TYPES]["schema"]>[Name]
  > &
    (Name extends keyof Service[typeof SERVICE_TYPES]["models"]
      ? ConsumerExtensions<Service[typeof SERVICE_TYPES]["models"][Name]>
      : {});
} & {
  /**
   * Runs a callback in a portable transaction without nested portable transactions.
   * @typeParam Value - Callback result.
   * @param run - Callback receiving transaction-bound table operations.
   * @returns Callback result after native commit, or original failure after rollback.
   */
  readonly transaction: <Value>(
    run: (context: DatabaseContext<Service>) => MaybePromise<Value>,
  ) => Promise<Value>;
  readonly zodSchemas: {
    readonly [Name in keyof TablesOf<Service[typeof SERVICE_TYPES]["schema"]>]: TableZodSchemas<
      TablesOf<Service[typeof SERVICE_TYPES]["schema"]>[Name]
    >;
  };
};

import { expect, test } from "bun:test";
import { is, StringChunk, type SQL } from "drizzle-orm";
