const version = [...versions][0]!;
for (const template of packedTemplates) {
  const path = join(root, "templates", "default", "v1", template, "package.json");
  const manifest = JSON.parse(await readFile(path, "utf8")) as TemplateManifest;
  for (const field of dependencyFields) {
    const dependencies = manifest[field];
    if (dependencies === undefined) continue;
    for (const name of Object.keys(dependencies))
      if (name.startsWith("@relkit/") || name === "create-relkit") dependencies[name] = version;
  }
  await syncJson(path, manifest);
}

const templateReadme = join(root, "templates", "default", "README.md");
const readme = await readFile(templateReadme, "utf8");
const nextReadme = readme.replace(
  /checked-in RelKit package version \(`[^`]+`\)/,
  `checked-in RelKit package version (\`${version}\`)`,
);
if (readme !== nextReadme) {
  if (write) await writeFile(templateReadme, nextReadme);
  else stale.push(templateReadme);
}

if (stale.length > 0)
  throw new Error(
    `Release metadata is stale; run bun run release:sync:\n${stale.map((path) => path.replace(`${root}/`, "")).join("\n")}`,
  );

import { cp, mkdir, symlink, writeFile } from "node:fs/promises";
import { join } from "node:path";

/** Creates a disposable copy of the auth example with database lifecycle probes. */
export async function writeGeneratedHostFixture(root: string, repository: string): Promise<void> {
  const example = join(repository, "examples/auth-drizzle");
  for (const path of ["src", "drizzle", "relkit.config.ts", "package.json"]) {
    await cp(join(example, path), join(root, path), { recursive: true });
  }
  const tsconfig = await Bun.file(
    join(repository, "templates/default/v1/minimal/tsconfig.json"),
  ).json();
  tsconfig.files.push(".relkit/generated/context-registry.d.ts");
  await writeFile(join(root, "tsconfig.json"), JSON.stringify(tsconfig));
  await symlink(join(example, "node_modules"), join(root, "node_modules"), "dir");
  const schema = await Bun.file(join(root, "src/database/schema/index.ts")).text();
  await writeFile(
    join(root, "src/database/schema/index.ts"),
    `${schema}\nexport const records = sqliteTable("records", {
  id: integer().primaryKey(), value: text().notNull(),
});\n`,
  );
  const files = {
    "src/database/service.ts": `import { appendFileSync } from "node:fs";
import { Database } from "bun:sqlite";
import { defineDrizzleService } from "@relkit/drizzle";
import { drizzle } from "drizzle-orm/bun-sqlite";
import * as schema from "./schema/index.js";
import recordsModel from "./models/records.model.js";
export default defineDrizzleService({
  schema,
  models: { records: recordsModel },
  client: ({ env }) => drizzle({ client: new Database(env.DATABASE_PATH) }),
  dispose: (database) => {
    database.$client.close();
    appendFileSync(process.env.RELKIT_TEST_RELEASES!, "released\\n");
  },
});
`,
    "src/database/lifecycle.ts": `import { activateDrizzleService, defineDrizzleService, type ApplicationEnv } from "@relkit/drizzle";
import { activateBetterAuthService } from "@relkit/better-auth";
import { Database } from "bun:sqlite";
import { drizzle } from "drizzle-orm/bun-sqlite";
import database from "./service.js";
import * as schema from "./schema/index.js";
import auth from "@app/auth/service.js";
export async function probeLifecycle(context: unknown, env: ApplicationEnv): Promise<{ shared: boolean; isolated: boolean; recovered: boolean }> {
  const shared = await activateDrizzleService(database, env);
  const again = await activateDrizzleService(database, { DATABASE_PATH: "ignored.sqlite" });
  const isolated = await activateDrizzleService(database, env, { isolated: true });
  const sharedAuth = await activateBetterAuthService(auth, shared, "/api/auth");
  const isolatedAuth = await activateBetterAuthService(auth, isolated, "/api/auth", { isolated: true });
  let attempts = 0;
  const retry = defineDrizzleService({
    schema,
    client: (context) => {
      if (++attempts === 1) throw new Error("fixture acquisition failure");
      return drizzle({ client: new Database(String(context.env.DATABASE_PATH)) });
    },
    dispose: (client) => client.$client.close(),
  });
  let failed = false;
  try { await activateDrizzleService(retry, env); } catch { failed = true; }
  const recovered = await activateDrizzleService(retry, env);
  const result = {
    shared: shared === again && shared.context === context,
    isolated: isolated !== shared && isolatedAuth !== sharedAuth,
    recovered: failed && attempts === 2,
  };
  await Promise.all([isolated.close(), recovered.close()]);
  return result;
}
`,
    "src/database/models/records.model.ts": `import { defineModel } from "@relkit/drizzle";
import { records } from "../schema/index.js";
import { probeLifecycle } from "../lifecycle.js";
export default defineModel({
  table: records,
  extend: { ownership: (_context, context: unknown, databasePath: string) =>
    probeLifecycle(context, { DATABASE_PATH: databasePath }) },
});
`,
    "src/records/service.ts": `import { defineService } from "@relkit/app/services";
import probe from "./functions/probe.function.js";
export default defineService({ functions: { probe } });
`,
    "src/records/functions/probe.function.ts": `import { defineFunction } from "@relkit/app/functions";
import { z } from "@relkit/app/schema";
export default defineFunction({
  input: z.object({ mode: z.union([z.literal("write"), z.literal("rollback"), z.literal("read"), z.literal("ownership")]) }),
  output: z.object({ count: z.number(), shared: z.boolean(), isolated: z.boolean(), recovered: z.boolean() }),
  handler: async ({ mode }, context) => {
    let ownership = { shared: false, isolated: false, recovered: false };
    if (mode === "write") await context.database.records.insert({ data: { id: 1, value: "kept" } });
    if (mode === "rollback") {
      try {
        await context.database.transaction(async (transaction) => {
          await transaction.records.insert({ data: { id: 2, value: "rolled back" } });
          throw new Error("fixture rollback");
        });
      } catch (error) {
        if (!(error instanceof Error) || error.message !== "fixture rollback") throw error;
      }
    }
    if (mode === "ownership") ownership = await context.database.records.ownership(context.database, String(context.env.DATABASE_PATH));
    return { count: (await context.database.records.findMany()).length, ...ownership };
  },
});
`,
    "src/routes/records/route.ts": `import { defineRoute } from "@relkit/app/routes";
import records from "@app/records/service.js";
export const POST = defineRoute({ target: records.probe });
`,
  };
  for (const [path, source] of Object.entries(files)) {
    const target = join(root, path);
    await mkdir(join(target, ".."), { recursive: true });
    await writeFile(target, source);
  }
}

import { expect, test } from "bun:test";
import { Database } from "bun:sqlite";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { buildProject } from "../../../packages/cli/src/commands/build.js";
import { writeGeneratedHostFixture } from "./generated-host-fixture.js";

test("generated host preserves database/auth ownership, rollback, session admission and shutdown", async () => {
  const repository = resolve(import.meta.dir, "../../..");
  const root = await mkdtemp(join(tmpdir(), "relkit-specialized-host-"));
  const probe = Bun.serve({ port: 0, fetch: () => new Response() });
  const baseURL = `http://127.0.0.1:${probe.port}`;
  const port = probe.port;
  await probe.stop(true);
  let host: Bun.Subprocess<"ignore", "pipe", "pipe"> | undefined;
  let output: Promise<string[]> | undefined;
  const databasePath = join(root, "test.sqlite");
  const releasesPath = join(root, "releases.txt");
  try {
    await writeGeneratedHostFixture(root, repository);
    const sqlite = new Database(databasePath);
    try {
      sqlite.exec(await readFile(join(root, "drizzle/20260831094750_auth/migration.sql"), "utf8"));
      sqlite.exec("create table records (id integer primary key, value text not null)");
    } finally {
      sqlite.close();
    }
    const built = await buildProject({ projectRoot: root });
    expect(built.ok, JSON.stringify(built.diagnostics)).toBe(true);
    const generated = await readFile(join(root, ".relkit/build/server/index.ts"), "utf8");
    expect(generated).toContain("instrumentation: specializedInstrumentation");
    host = Bun.spawn([process.execPath, "run", "--no-env-file", ".relkit/build/server/index.js"], {
      cwd: root,
      env: {
        ...process.env,
        PORT: String(port),
        NODE_ENV: "test",
        DATABASE_PATH: databasePath,
        BETTER_AUTH_URL: baseURL,
        BETTER_AUTH_SECRET: "generated-host-test-secret-at-least-32-bytes",
        RELKIT_TEST_RELEASES: releasesPath,
        RELKIT_DRAIN_TIMEOUT_MS: "5000",
        RELKIT_TELEMETRY_FLUSH_TIMEOUT_MS: "1000",
      },
      stdin: "ignore",
      stdout: "pipe",
      stderr: "pipe",
    });
    output = Promise.all([new Response(host.stdout).text(), new Response(host.stderr).text()]);
    const deadline = Date.now() + 20_000;
    let ready = false;
    while (Date.now() < deadline && host.exitCode === null) {
      try {
        ready = (await fetch(`${baseURL}/session`, { signal: AbortSignal.timeout(1000) })).ok;
        if (ready) break;
      } catch {
        /* The owned child has not started listening yet. */
      }
      await Bun.sleep(25);
    }
    expect(
      ready,
      host.exitCode === null ? "Generated host startup timed out" : (await output).join("\n"),
    ).toBe(true);
    const request = (path: string, options: RequestInit = {}) =>
      fetch(`${baseURL}${path}`, options);
    const records = async (mode: string) => {
      const response = await request("/records", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ mode }),
      });
      const result = await response.json();
      expect(response.status, JSON.stringify(result)).toBe(200);
      return result;
    };
    expect(await records("write")).toMatchObject({ count: 1 });
    expect(await records("rollback")).toMatchObject({ count: 1 });
    expect(await records("read")).toMatchObject({ count: 1 });
    expect(await records("ownership")).toMatchObject({
      count: 1,
      shared: true,
      isolated: true,
      recovered: true,
    });
    expect((await request("/account/profile")).status).toBe(401);
    const signup = await request("/api/auth/sign-up/email", {
      method: "POST",
      headers: { "content-type": "application/json", origin: baseURL },
      body: JSON.stringify({
        name: "Generated Host",
        email: "host@example.com",
        password: "host-password-123",
      }),
    });
    expect(signup.status, await signup.text()).toBe(200);
    const cookie = signup.headers.get("set-cookie")?.split(";", 1)[0];
    expect(cookie).toContain("better-auth");
    const headers = { cookie: cookie ?? "" };
    const session = await request("/api/auth/get-session", { headers });
    expect(await session.json()).toMatchObject({ user: { email: "host@example.com" } });
    const profile = await request("/account/profile", { headers });
    expect(profile.status).toBe(200);
    expect(await profile.json()).toMatchObject({ authenticated: true });
    expect((await readFile(releasesPath, "utf8")).trim().split("\n")).toHaveLength(1);
    host.kill("SIGTERM");
    expect(await host.exited).toBe(0);
    expect((await readFile(releasesPath, "utf8")).trim().split("\n")).toHaveLength(2);
    expect((await output).join("\n")).not.toContain("host-password-123");
    expect((await output).join("\n")).not.toContain("generated-host-test-secret-at-least-32-bytes");
  } finally {
    if (host?.exitCode === null) {
      host.kill("SIGTERM");
      await host.exited;
    }
    await output;
    await rm(root, { recursive: true, force: true });
  }
}, 90_000);
